\begin{align*}
   \eqref{eq:introspecexp} \leq \sqrt{AD \, \mathcal{K}\, \mathcal{R}},
\end{align*}
where
\begin{align*}
    \mathcal{R} = \frac{1}{C/A} \sum_{\varphi \in \mathcal{B}(q)} h(\varphi)\bigg|   \sum_{n \leq C/A} \varrho_{\varphi}(n) \bigg|^2 
\end{align*}
and 
\begin{align} \mathcal{K} =\sum_{\varphi \in \mathcal{B}(q)}   h(\varphi)\bigg| \sum_{\tau \in  \Gamma \backslash \mathcal{M} } \alpha(\tau )\varphi(\tau)   \bigg|^2 =  \sum_{\tau_1,\tau_2 \in  \Gamma \backslash \mathcal{M} } \alpha(\tau_1 ) \overline{\alpha(\tau_2)} \sum_{\varphi \in \mathcal{B}(q)}  h(\varphi) \varphi(\tau_1) \overline{\varphi(\tau_2) }. 
\end{align}
The term $\mathcal{R}$ may be bounded by the spectral large sieve of Deshouillers and Iwaniec \cite{deshoullieriwaniec}.

To approach $\mathcal{K}$ we identify it as the spectral expansion of an automorphic kernel on $\operatorname{SL}_2({\mathbb R})$ (also known as pre-trace formula). Indeed, for a suitable function $h(\varphi)$ this gives the existence of a smooth function $k:\operatorname{SL}_2({\mathbb R}) \to {\mathbb C}$ supported on a small neighborhood of the identity, such that
\begin{align*}
   \sum_{\varphi \in \mathcal{B}(q)} h(\varphi) \varphi(\tau_1) \overline{\varphi(\tau_2) } = \sum_{\gamma \in \Gamma} k(\tau_2^{-1} \gamma \tau_1).
\end{align*}
Thus, denoting $g=\tau_2^{-1} \gamma \tau_1$ we get
\begin{align*}
    \mathcal{K} &=  \sum_{\gamma \in \Gamma} \sum_{\tau_1,\tau_2 \in  \Gamma \backslash \mathcal{M} } \alpha(\tau_1 ) \overline{\alpha(\tau_2)}  k(\tau_2^{-1} \gamma \tau_1)  \\
   \nonumber  &= \sum_{g \in \mathcal{M}^{-1} \mathcal{M}}  k(g)\sum_{\substack{\tau_1,\tau_2 \in  \Gamma \backslash \mathcal{M}  \\ \tau_2 g \tau_1^{-1} \in \Gamma }} \alpha(\tau_1 ) \overline{\alpha(\tau_2)}   \\
   \nonumber  & \leq  \sum_{g \in \mathcal{M}^{-1} \mathcal{M}}  |k(g)| \bigg|\sum_{\substack{\tau \in \Gamma \backslash \mathcal{M} \\ \tau g \in \mathcal{M} }} \alpha(\tau g ) \overline{\alpha(\tau)} \bigg|,
\end{align*}
which is almost of the shape as proposed in Theorem \ref{thm:mainblackbox}.

However, we have oversimplified in the above sketch in one crucial aspect. Namely, in the case that $\max\{ C/D,D/C\}$ is large, the smooth weight $F$  lives on a narrow part of the $\mathrm{K}$-component of the Iwasawa decomposition $\operatorname{SL}_2({\mathbb R})= \mathrm{N}\mathrm{A}\mathrm{K}$. Then the spectrum blows up in terms of the $\mathrm{K}$ types and the sum over $\varphi \in \mathcal{B}(q)$ actually runs over roughly $q \max\{ C/D,D/C\}$ many elements. This can be resolved by first rescaling the smooth weight 
\begin{align*}
    P_f(\tau) = \sum_{\gamma \in \Gamma} F(\gamma \tau) =   \sum_{\gamma \in \Gamma} F(\gamma \tau \mathrm{a}[D/C] \mathrm{a} [C/D]  ) =   P_{f_0}(\tau \mathrm{a}[D/C]),
\end{align*}
where 
\begin{align*}
    f_0(g) = f(g \mathrm{a} [C/D])  \in C_\delta^{7}(A_0,C_0,D_0)
\end{align*}
with
\begin{align*}
    C_0 = D_0 = \sqrt{CD}, \quad A_0D_0=AD, \quad \text{and} \quad C_0/A_0 = C/A.
\end{align*}
Alternatively, this can be seen as applying the spectral expansion to the original $P_f$ after the change of basis $\varphi(\tau) \mapsto \varphi(\tau \mathrm{a}[D/C])$.

Then by the above argument we need to bound
\begin{align} \begin{split}
  \sqrt{AD} &\sum_{\varphi \in \mathcal{B}(q)} h(\varphi) \bigg|  \frac{1}{\sqrt{C/A}} \sum_{n \leq C/A} \varrho_{\varphi}(n) \bigg| \bigg| \sum_{\tau \in  \Gamma \backslash \mathcal{M} } \alpha(\tau )\varphi(\tau \mathrm{a}[D/C])   \bigg|   
\end{split}
\end{align}
and we arrive at
\begin{align*}
     \mathcal{K} &=  \sum_{\gamma \in \Gamma} \sum_{\tau_1,\tau_2 \in  \Gamma \backslash \mathcal{M} } \alpha(\tau_1 ) \overline{\alpha(\tau_2)}  k( \mathrm{a}[D/C]^{-1}\tau_2^{-1} \gamma \tau_1 \mathrm{a}[D/C]) \\
     & \leq   \sum_{g \in \mathcal{M}^{-1} \mathcal{M}}  |k( \mathrm{a}[C/D] g \mathrm{a}[D/C])| \bigg|\sum_{\substack{\tau \in \Gamma \backslash \mathcal{M} \\ \tau g \in \mathcal{M} }} \alpha(\tau g ) \overline{\alpha(\tau)} \bigg|.
\end{align*}
Here we can show that for $g= \smqty(a & b \\ c& d)$ the weight $|k( \mathrm{a}[C/D] g \mathrm{a}[D/C])|$ vanishes outside 
\begin{align*}
    |a|  + |b| C/D +|c| D/C + |d| \leq 6.
\end{align*}
This gives the shape of $\mathcal{K}$ in Theorem \ref{thm:mainblackbox}.

To illustrate how the method may be applied, we sketch the proof of Corollary \ref{cor:fixedap} in the case $h=1$, $\gcd(r(r+1),q)=1$, using Theorem \ref{thm:mainblackbox} and assuming $\theta=0$. 

We have the following blueprint for applying our main theorem.
\begin{enumerate}
    \item Identify the largest symmetry by a congruence subgroup $\Gamma$ and the orbits $\Gamma \backslash \mathcal{M}$.
    \item Handle very skewed ranges trivially.
     \item Compute an upper bound for $\mathcal{K}$.
    \item Apply theorem.
\end{enumerate}

Consider the case of  Corollary \ref{cor:fixedap} with $h=1$. We write
\begin{align*}
    d(n) = \sum_{n=bc} 1, \quad \quad \quad d(n+1) = \sum_{n=ad} 1
\end{align*}
 and insert a smooth dyadic partition for $a,c,d$ via $f \in C^{7}_{\delta}(A,C,D)$ for some $A,C,D \ll X$ with $AD \asymp X$ and $\delta \asymp \eta$. Denote also $B:= X/C$.  This reduces matter to evaluating 
\begin{align*}
    \sum_{\substack{ad-bc = 1 \\ bc \equiv r \pmod{q} }} f(a,c,d).
\end{align*} 
Here we take
\begin{align*}
    \mathcal{M} = \operatorname{SL}_2({\mathbb Z}), \quad \alpha(\smqty(a & b \\ c& d)) = \mathbf{1}_{bc \equiv r \pmod{q}}.
\end{align*}
We then observe that $\alpha$ is invariant under the action of $\Gamma = \Gamma_2(q,q)$, since for any $ \smqty( a_0 & b_0 q \\  c_0 q & d_0) \in \Gamma_2(q,q)$ we have that
\begin{align*}
    \mqty( a_0 & b_0 q \\  c_0 q & d_0)  \mqty(a & b \\ c& d) = \mqty(\ast & a_0 b + q b_0 d \\ d_0 c + q c_0 a & \ast) 
\end{align*}
maps 
\begin{align*}
   bc \mapsto (a_0 b + q b_0 d) (d_0 c + q c_0 a) \equiv a_0 d_0 bc \equiv bc \pmod{q}.
\end{align*} 
Note that $\Gamma$ is in some sense too sparse a group. The original problem lives on a set of density roughly $1/q$ whereas $\Gamma$ has density roughly $1/q^2$ in $\operatorname{SL}_2({\mathbb Z})$. Consequently $\alpha$ has density roughly $1/q$ on the set of orbits $\Gamma \backslash \operatorname{SL}_2({\mathbb Z})$.

By symmetry (swapping $ad \leftrightarrow bc$, $a \leftrightarrow d$, $b \leftrightarrow c$) we may assume that 
\begin{align*}
    C \leq D \leq A \leq B.
\end{align*}
The very skewed ranges where
\begin{align*}
    \max \{ A,D \} \geq q C
\end{align*}
may be counted trivially (Poisson summation). In the complementary range we have
\begin{align}
     1\leq \frac{A}{C}, \frac{D}{C} \leq q.
\end{align}

To apply Theorem \ref{thm:mainblackbox} we need an upper bound for
\begin{align*}
  \mathcal{K} =   \sum_{\substack{g =\smqty(a & b \\mathfrak c & d) \in \operatorname{SL}_2({\mathbb Z}) \\  |a|+|b|C/D+|c|D/C+|d| \,\leq 6}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) 
 }} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr|.
\end{align*}
The contribution from $g = I$ is bounded by
\begin{align*}
    \sum_{\tau \in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) } |\alpha(\tau)|^2 \ll q 
\end{align*}
and we can never hope to get a better bound. The contribution from $ad \neq 1$ satisfies a similar bound $\ll q$ by Cauchy-Schwarz and using the divisor bound for $c |ad-1$. Finally, since $1 \leq D/C \leq q$ and since for generic $g \in \operatorname{SL}_2({\mathbb Z})$ the function $\tau \mapsto \alpha(\tau) \overline{\alpha(\tau g)}$ has density $1/q \cdot 1/q = 1/q^2$, we have
\begin{align*}
    \sum_{\substack{g =\smqty(\pm 1 & b \\0 & \pm 1) \in \operatorname{SL}_2({\mathbb Z}) \\ 0< |b| \,\leq 6 D/C}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) 
 }} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr| \ll  D/C \ll  q,
\end{align*}
so that $\mathcal{K} \ll  q$. In fact, it is easy to check that for $\gcd(r(r+1),q)=1$ we have  
\begin{align*}
    |\sum_{ \substack{\tau\in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) 
 }} \alpha(\tau) \overline{\alpha(\tau g)} |  \ll \gcd(b,q), \quad \quad g =\mqty(\pm 1 & b \\0 & \pm 1).
\end{align*}

Using $1 <A/C \leq q$ and our assumption that  $\theta=0$, we get
\begin{align*}
    \mathcal{ R} \ll 1 + \frac{C}{Aq} + \frac{A}{Cq} \ll 1.
\end{align*}
Thus, applying Theorem \ref{thm:mainblackbox} we get a main term of size roughly $X/q$ and an error term that is bounded by
\begin{align*}
    \sqrt{AD \, \mathcal{K} \, \mathcal{R}} \ll X^{1/2} q^{1/2}.
\end{align*}
This is dominated by the main term as long as $q$ is a bit smaller than $X^{1/3}$.

Consider the case of  Corollary \ref{cor:fixedap} with $h=1$. We write
\begin{align*}
    d(n) = \sum_{n=bc} 1, \quad \quad \quad d(n+1) = \sum_{n=ad} 1
\end{align*}
 and insert a smooth dyadic partition for $a,c,d$ via $f \in C^{7}_{\delta}(A,C,D)$ for some $A,C,D \ll X$ with $AD \asymp X$ and $\delta \asymp \eta$. Denote also $B:= X/C$.  This reduces matter to evaluating 
\begin{align*}
    \sum_{\substack{ad-bc = 1 \\ bc \equiv r \pmod{q} }} f(a,c,d).
\end{align*}

Here we take
\begin{align*}
    \mathcal{M} = \operatorname{SL}_2({\mathbb Z}), \quad \alpha(\smqty(a & b \\ c& d)) = \mathbf{1}_{bc \equiv r \pmod{q}}.
\end{align*}
We then observe that $\alpha$ is invariant under the action of $\Gamma = \Gamma_2(q,q)$, since for any $ \smqty( a_0 & b_0 q \\  c_0 q & d_0) \in \Gamma_2(q,q)$ we have that
\begin{align*}
    \mqty( a_0 & b_0 q \\  c_0 q & d_0)  \mqty(a & b \\ c& d) = \mqty(\ast & a_0 b + q b_0 d \\ d_0 c + q c_0 a & \ast) 
\end{align*}
