\begin{align*}
   bc \mapsto (a_0 b + q b_0 d) (d_0 c + q c_0 a) \equiv a_0 d_0 bc \equiv bc \pmod{q}.
\end{align*}

By symmetry (swapping $ad \leftrightarrow bc$, $a \leftrightarrow d$, $b \leftrightarrow c$) we may assume that 
\begin{align*}
    C \leq D \leq A \leq B.
\end{align*}
