\begin{align*}
  \mathcal{K} =   \sum_{\substack{g =\smqty(a & b \\mathfrak c & d) \in \operatorname{SL}_2({\mathbb Z}) \\  |a|+|b|C/D+|c|D/C+|d| \,\leq 6}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) 
 }} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr|.
\end{align*}
The contribution from $g = I$ is bounded by
\begin{align*}
    \sum_{\tau \in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) } |\alpha(\tau)|^2 \ll q 
\end{align*}
and we can never hope to get a better bound. The contribution from $ad \neq 1$ satisfies a similar bound $\ll q$ by Cauchy-Schwarz and using the divisor bound for $c |ad-1$. Finally, since $1 \leq D/C \leq q$ and since for generic $g \in \operatorname{SL}_2({\mathbb Z})$ the function $\tau \mapsto \alpha(\tau) \overline{\alpha(\tau g)}$ has density $1/q \cdot 1/q = 1/q^2$, we have
\begin{align*}
    \sum_{\substack{g =\smqty(\pm 1 & b \\0 & \pm 1) \in \operatorname{SL}_2({\mathbb Z}) \\ 0< |b| \,\leq 6 D/C}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) 
 }} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr| \ll  D/C \ll  q,
\end{align*}
so that $\mathcal{K} \ll  q$. In fact, it is easy to check that for $\gcd(r(r+1),q)=1$ we have  
\begin{align*}
    |\sum_{ \substack{\tau\in \Gamma \backslash  \operatorname{SL}_2({\mathbb Z}) 
 }} \alpha(\tau) \overline{\alpha(\tau g)} |  \ll \gcd(b,q), \quad \quad g =\mqty(\pm 1 & b \\0 & \pm 1).
\end{align*}

Using $1 <A/C \leq q$ and our assumption that  $\theta=0$, we get
\begin{align*}
    \mathcal{ R} \ll 1 + \frac{C}{Aq} + \frac{A}{Cq} \ll 1.
\end{align*}
Thus, applying Theorem \ref{thm:mainblackbox} we get a main term of size roughly $X/q$ and an error term that is bounded by
\begin{align*}
    \sqrt{AD \, \mathcal{K} \, \mathcal{R}} \ll X^{1/2} q^{1/2}.
\end{align*}
This is dominated by the main term as long as $q$ is a bit smaller than $X^{1/3}$.

For Theorem \ref{cor:Lfunction} we apply the approximate functional equation,  use the group $\Gamma_2(q_1,q_2)$, and check that
\begin{align*}
    \alpha(\smqty(a &b \\ c& d)) = \chi_1(a) \overline{\chi_1}(b) \overline{\chi_2}(c) \chi_2(d)
\end{align*}
is left-invariant. In fact, here we average also over the determinant
\begin{align*}
    \sum_{h \sim H} \sum_{ad-bc=h}     \alpha(\smqty(a &b \\ c& d))f(a,c,d), \quad H \ll \frac{AD}{T}, \, T \ll AD,BC \ll T \sqrt{q_1q_2} .
\end{align*}
This and a good dependency on the size of $h$ in other applications is facilitated by the more technical Theorem \ref{thm:twisteddetwbound}. In this case a strong bound for $\mathcal{K}$ is a consequence of an elementary character sum bound, which captures the oscillations in $\alpha$ from the characters.

For Theorem \ref{cor:Lfunction} we apply the approximate functional equation,  use the group $\Gamma_2(q_1,q_2)$, and check that
\begin{align*}
    \alpha(\smqty(a &b \\ c& d)) = \chi_1(a) \overline{\chi_1}(b) \overline{\chi_2}(c) \chi_2(d)
\end{align*}
is left-invariant.

In fact, here we average also over the determinant
\begin{align*}
    \sum_{h \sim H} \sum_{ad-bc=h}     \alpha(\smqty(a &b \\ c& d))f(a,c,d), \quad H \ll \frac{AD}{T}, \, T \ll AD,BC \ll T \sqrt{q_1q_2} .
\end{align*}
This and a good dependency on the size of $h$ in other applications is facilitated by the more technical Theorem \ref{thm:twisteddetwbound}.

We start by introducing two coordinate systems for the Lie group 
\begin{align*}
 G:=  \operatorname{SL}_2({\mathbb R})  = \bigg\{ \mqty(a&b \\ c& d) : a,b,c,d \in {\mathbb R}, ad-bc=1  \bigg\} 
\end{align*}
following mostly the notation in \cite{motohashielements}.

The relevant subgroups for us are
\begin{align*}
    \mathrm{N} :=& \bigg\{ \mathrm{n}[x] =  \mqty(1&x \\ & 1) : x \in {\mathbb R}  \bigg\}  \\
      \mathrm{A} := & \bigg\{ \mathrm{a}[y]= \mqty(\sqrt{y }& \\ & 1/\sqrt{y}) : y \in (0,\infty)  \bigg\} \\
        \mathrm{K} := &\bigg\{ \mathrm{k}[\theta] =  \mqty(\cos \theta & \sin \theta \\ -\sin \theta & \cos \theta) : \theta \in {\mathbb R} / 2\pi {\mathbb Z} \bigg\}  
\end{align*}

We then have the \emph{Iwasawa decomposition}
\begin{align*}
    G= \mathrm{N} \mathrm{A} \mathrm{K}  ,
\end{align*}
where the representation $g= \smqty(a& b \\ c & d) = \mathrm{n}[x] \mathrm{a}[y] \mathrm{k}[\theta]$ is uniquely defined for $\theta \in [0,2\pi)$ via
\begin{align} x= \frac{ac+bd}{c^2+d^2},\quad y= \frac{1}{c^2+d^2}, \quad \theta = \arctan \bigg(-\frac{c}{d}\bigg)
\end{align}
and 
\begin{align} \mathrm{n}[x] \mathrm{a}[y] \mathrm{k}[\theta] = \mqty( \sqrt{y} \cos \theta  - \frac{x}{\sqrt{y}} \sin \theta   &  \sqrt{y} \sin \theta  + \frac{x}{\sqrt{y}} \cos \theta \\ - \frac{1}{\sqrt{y}} \sin \theta &\frac{1}{\sqrt{y}} \cos \theta ).
\end{align}

We also have the \emph{Cartan decomposition}
\begin{align*}
    G= \mathrm{K} \mathrm{A} \mathrm{K},
\end{align*}
where the representation $g = \mathrm{k}[\varphi] \mathrm{a}[e^{-\varrho}]\mathrm{k}[\vartheta] $ is unique provided that $\varrho > 0$ and $\varphi \in [0,\pi)$. We have
\begin{align} \mathrm{k}[\varphi] \mathrm{a}[e^{\varrho}]\mathrm{k}[\vartheta] = \mathrm{k}[\varphi + \pi/2] \mathrm{a}[e^{-\varrho}]\mathrm{k}[\vartheta - \pi/2] = \mathrm{k}[\varphi + \pi] \mathrm{a}[e^{\varrho}]\mathrm{k}[\vartheta - \pi].
\end{align}

The  Cartan coordinates are best described by the isomorphism of groups via conjugation by the Cayley matrix $\mathcal{C} = \smqty(1 & -i \\ 1 & i)$, which diagonalizes $\mathrm{K}$, 
\begin{align*}
    \operatorname{SL}_2({\mathbb R}) &\cong \operatorname{SU}_{1,1}({\mathbb R}) := \bigg\{ \mqty( \alpha & \beta \\ \overline{\beta} & \overline{\alpha}): \alpha,\beta \in {\mathbb C}, \, |\alpha|^2-|\beta|^2 = 1    \bigg\}, \\
    g &\mapsto \mathcal{C} g \mathcal{C}^{-1}.
\end{align*}

Denoting 
\begin{align*}
u(z,w):= \frac{|z-w|^2}{4 \operatorname{Im}(z) \operatorname{Im}(w)}, \quad z,w\in \mathbb{H},    
\end{align*}
 we have $\cosh(\varrho) = 2u(gi,i) +1$ and for $g= \smqty(a & b \\ c& d) \in G$
 \begin{align} u(gi, i) = \tfrac{1}{4}  (a^2+b^2+c^2+d^2-2).
 \end{align}

Following the notation in \cite{motohashielements},
we introduce matrices
\begin{align*}
    \mathrm{X}_1 := \mqty(\,\,&1 \\ \,\, &),  \quad \mathrm{X}_2 := \mqty(1& \\ &-1), \quad  \mathrm{X}_3 := \mqty( & 1 \\ -1 & ),
\end{align*}
which are the infinitesimal generators for the subgroups
\begin{align*}
    \mathrm{N} = \{\operatorname{exp}( t \mathrm{X}_1): t \in {\mathbb R}\}, \,    \mathrm{A} = \{\operatorname{exp}( t \mathrm{X}_2): t \in {\mathbb R}\}, \, \mathrm{K} = \{\operatorname{exp}( t \mathrm{X}_3): t \in {\mathbb R}\}.
\end{align*}

We then define the right Lie differentials
\begin{align*}
    \mathrm{x_j}f(g) := \partial_t f(g \,\operatorname{exp}(t \mathrm{X}_j)) |_{t=0}.
\end{align*}

By construction these operators are left-invariant under the action of the group $G$ on itself. That is, denoting
\begin{align*}
    l_h: f(g) \mapsto f(hg), \quad r_h: f(g) \mapsto f(gh),
\end{align*}
we have $\mathrm{x}_j l_h=l_h\mathrm{x}_j$ for $j\in\{1,2,3\}$.

We construct the \emph{raising and lowering operators}
\begin{align*}
    \mathrm{e}^+ :=& 2 \mathrm{x}_1 + \mathrm{x}_2-i\mathrm{x}_3, \\
      \mathrm{e}^- :=& -2i \mathrm{x}_1 + \mathrm{x}_2+i\mathrm{x}_3.
\end{align*}

The \emph{Casimir operator} is then defined as
\begin{align}
    \Omega := -\frac{1}{4}  \mathrm{e}^{+}  \mathrm{e}^{-} + \frac{1}{4}\mathrm{x}_3^2 - \frac{1}{2} i \mathrm{x}_3.
\end{align}

The Casimir element is not only left-invariant but also right-invariant under the action of the group $G$, that is,
\begin{align} \Omega l_h =  l_h \Omega, \quad  \Omega r_h =  r_h \Omega.
\end{align}

In the Cartan coordinates $\mathrm{k}[\varphi] \mathrm{a}[e^{-\varrho}]\mathrm{k}[\vartheta]$, denoting  $\cosh \varrho =2u+1,$ we have
\begin{align} \begin{split}
    \Omega =&  - \partial_\varrho^2 - \frac{1}{\tanh \varrho} \partial_\varrho -\frac{1}{4\sinh^2 \varrho} \partial_\varphi^2  +\frac{1}{2 \sinh\varrho \tanh \varrho} \partial_\varphi \partial_\vartheta - \frac{1}{4 \sinh^2 \varrho}  \partial_\vartheta^2 \\
        =& -u(u+1) \partial_u^2 - (2u+1) \partial_u - \frac{1}{16u(u+1)}  \partial_\varphi^2   +   \frac{2u+1}{4 u(u+1)}\partial_\varphi \partial_\vartheta -  \frac{1}{16u(u+1)} \partial_\vartheta^2 .
\end{split}
\end{align}

From this we see that $\Omega$ commutes with taking inverses: If
\begin{align*}
    \iota: f(g) \mapsto f(g^{-1}),
\end{align*}
then
\begin{align} \Omega \iota = \iota \Omega 
\end{align}
since
\begin{align*}
    (\mathrm{k}[\varphi] \mathrm{a}[e^{-\varrho}] \mathrm{k}[\vartheta])^{-1} =   \mathrm{k}[-\vartheta]\mathrm{a}[e^{\varrho}] \mathrm{k}[-\varphi] =\mathrm{k}[\pi/2-\vartheta]\mathrm{a}[e^{-\varrho}] \mathrm{k}[-\pi/2-\varphi].
\end{align*}

Let $\ell \in {\mathbb Z}$ and $\nu \in {\mathbb C}$. The functions (defined using the Iwasawa coordinates)
\begin{align} \phi_{\ell}(g,\nu):=y^{\nu+1/2} e^{ i\ell \theta}
\end{align}
 are eigenfunctions of the Casimir operator $\Omega$ on $G$
\begin{align*}
    \Omega   \phi_{\ell}(g,\nu) = \bigg(\frac{1}{4}-\nu^2\bigg) \phi_{\ell}(g,\nu).
\end{align*}

Furthermore, the functions $ \phi_{\ell}(g,\nu)$ are of \emph{right-type} $\ell$, by which we mean that
\begin{align*}
 \phi_{\ell}(g \mathrm{k}[\theta],\nu) = e^{i \ell \theta}   \phi_{\ell}(g,\nu).
\end{align*}
The notion of functions with \emph{left-type} $\ell$ is defined similarly.

The invariant Haar measure $\mathrm d g$ on $G$ is defined in terms of the Iwasawa and Cartan coordinates via (note the swap between $\mathrm{a}$ and $\mathrm{n}$)
\begin{align} \begin{split}
     \mathrm d \mathrm{n}[x] = \mathrm d x, \quad & \mathrm d \mathrm{a}[y] = \frac{\mathrm d y}{y}, \quad \mathrm d \mathrm{k}[\theta] = \frac{\mathrm d \theta}{2\pi}, \\
   \int_G  f(g)\mathrm d g =& \int_{\mathrm{A} \times \mathrm{N} \times \mathrm{K}} f(\mathrm{a} \mathrm{n} \mathrm{k})  \mathrm d \mathrm{a}\mathrm d \mathrm{n} \mathrm d \mathrm{k}  =    \int_{{\mathbb R}\times {\mathbb R}_{>0} \times {\mathbb R}/2\pi{\mathbb Z}} f(\mathrm{n}[x] \mathrm{a}[y] \mathrm{k}[\theta]) \frac{\mathrm d x \mathrm d y \mathrm d \theta}{2\pi y^2} \\
   =&\int_{\mathrm{K} \times \mathrm{K}} \int_{{\mathbb R}_{>0}} f(\mathrm{k}_1 \mathrm{a}[e^{-\varrho}] \mathrm{k}_2)  \sinh(\varrho) \mathrm d \varrho \,\mathrm d \mathrm{k}_1 \mathrm d \mathrm{k}_2
\end{split}
\end{align}

Then
\begin{align}
    \int_{\Gamma_0(q)\backslash G} \mathrm d g= [\operatorname{SL}_2({\mathbb Z}): \Gamma_0(q)] \int_{\operatorname{SL}_2({\mathbb Z})\backslash \operatorname{SL}_2({\mathbb R})} \mathrm d g= \frac{\pi}{6} q \prod_{p|q}(1+p^{-1}). \, 
\end{align}

In terms of the matrix coordinates we have (by using \eqref{eq:matrixtoiwasawa} to compute the Jacobian determinant)
\begin{align*}
    \mathrm d g = \frac{\mathrm d x \mathrm d y \mathrm d \theta}{2\pi y^2} = \frac{1}{\pi} \frac{\mathrm d a \mathrm d c \mathrm d d}{c}.
\end{align*}

Thus, using $\zeta(2) = \pi^2/6$ we have for any integrable $F:G \to{\mathbb C}$
\begin{align} \frac{1}{ |\Gamma_0(q)\backslash G|}    \int_G  F(g)\mathrm d g = \frac{1}{  \zeta(2) \, q \, \prod_{p|q}(1+p^{-1})}   \int_{{\mathbb R}^3}  F(\smqty(a & \ast \\ c & d)) \frac{\mathrm d a \mathrm d c \mathrm d d}{c}.
\end{align}

The inner product on $L^2(G)$ is defined by
\begin{align*}
    \langle f_1,f_2\rangle_G := \int_G f_1(g) \overline{f_2(g)} \mathrm d g.
\end{align*}

Let $\chi$ be a Dirichlet character to the modulus $q$. This defines a character on $\Gamma$ via
\begin{align*}
    \chi(\smqty(a &b \\ c & d)) := \chi(d) = \overline{\chi}(a).
\end{align*}

We denote 
\begin{align*}
    \langle f_1,f_2 \rangle_{\Gamma \backslash G}:=   \int_{\Gamma \backslash G} f_1(g) \overline{f_2(g)} \mathrm d g
\end{align*}
and
\begin{align*}
    L^2(\Gamma \backslash G,\chi) := \{f: G \to {\mathbb C}: f(\gamma g) = \chi(\gamma) f(g), \quad  \langle f,f \rangle_{\Gamma \backslash G} < \infty\}.
\end{align*}

Let $ \phi_{\ell}(g,\nu)$ be as  in \eqref{eq:phibasicdefinition} and suppose that $\ell \equiv \kappa \pmod{2}$. For $\mathfrak{c}\in \mathfrak{C}(q,\chi)$, we define the Eisenstein series for ${\mathbb R}(\nu)>1/2$ by
\begin{align*}
    E_{\mathfrak{c}}^{(\ell)}(g,\nu)=\sum_{\gamma\in \Gamma_{\mathfrak{c}}\setminus \Gamma } \overline{\chi}(\gamma) \phi_\ell (\sigma_{\mathfrak{c}}^{-1} \gamma g, \nu),
\end{align*}
where $\Gamma_{\mathfrak{c}}$ is the stabilising group and $\sigma_{\mathfrak{c}}$ a scaling matrix of the cusp $\mathfrak{c}$.

Proposition \ref{prop:specdecompL2} follows from \cite[Section 4]{DFIartin}, by identifying for a fixed $\ell$ the basis elements $u_j$ of weight $k_{\text{DFI}}=\ell$ in  \cite[(4.50))]{DFIartin} via
\begin{align*}
  \varphi_V^{(\ell)}(\mathrm{n}[x] \mathrm{a}[y] \mathrm{k}[\theta])=  u_j(x+iy) e^{i\ell \theta},
\end{align*}
and similarly for the Eisenstein series.

Each $V$ splits into subspaces according to the right-action by $\mathrm{K}$
\begin{align*}
    V = \bigoplus_{\ell \equiv \kappa \pmod{2}} V^{(\ell)},
\end{align*}
where $V^{(\ell)}$ is a one or zero dimensional subspace consisting of functions of right-type $\ell$.

We pick generators $\varphi^{(\ell)}_V$ for each $V^{(\ell)}$ such that
\begin{align*}
    \langle \varphi^{(\ell)}_V, \varphi^{(\ell)}_V \rangle_{\Gamma \backslash G} =1
\end{align*}
to get an orthonormal basis.

The cuspidal spectrum $\mathcal{B}(q,\chi)$ splits into three parts
\begin{enumerate}
    \item Regular spectrum: $\nu_V \in i {\mathbb R}$
    \item Exceptional spectrum: $\nu_V \in (0,1/2)$
    \item Discrete series: $\nu_V =  \frac{k-1}{2}, \quad k > 0, \quad k \equiv \kappa \pmod{2}$.
    \end{enumerate}

For the discrete series $\nu_V = k-1/2$ we call $k$ the \emph{weight} and we have either
\begin{align*}
    V = \bigoplus_{\substack{\ell  \geq k\\ \ell \equiv \kappa\pmod{2}}} V^{(\ell)} \quad \text{or} \quad   V= \bigoplus_{\substack{\ell  \leq - k\\  \ell \equiv \kappa\pmod{2}}} V^{(\ell)}.
\end{align*}

To state the Fourier expansion, we use the Jacquet operator $\mathcal{A}^{\pm}$. For a function $\phi$ on $G$ it is defined as
\begin{align*}
    \mathcal{A}^\pm \phi(g)=\int_{-\infty}^\infty e(\mp \xi) \phi( \mathrm w \mathrm{n}[\xi] g) \mathrm d \xi,
\end{align*}
where 
\begin{align*}
    \mathrm w=\mathrm{k}[\pi/2]=\mqty(0 & 1 \\ -1 & 0) 
\end{align*}
is the Weyl element of $G$.

The Hecke operator on $L^2(\Gamma_0(q)\backslash G,\chi)$  is defined by
\begin{align} \mathcal{T}_h f(g) :=  \frac{1}{\sqrt{h}} \sum_{ad=h} \chi(a) \sum_{b  \pmod{d}} f\bigg(\frac{1}{\sqrt{h}}\mqty(a & b  \\ & d)g\bigg).
\end{align}

It satisfies the multiplicativity relation
\begin{align*}
    \mathcal{T}_m \mathcal{T}_n = \sum_{d | \gcd(m,n)} \chi(d)\mathcal{T}_{mn/d^2}. 
\end{align*}

For $\gcd(h,q)=1$ the Hecke eigenvalues satisfy the multiplicativity relation
\begin{align*}
  \lambda_V(h) \varrho_V(n) = \sum_{d | \gcd(h,n)} \chi(d) \varrho_V(hn/d^2),  
\end{align*}
and similarly for the Eisenstein series.

The Ramanujan-Petersson conjecture states that also in the cuspidal spectrum
\begin{align*}
 |\lambda_{V}(h)| \ll_\varepsilon |h|^{\varepsilon}.
\end{align*}

The automorphic forms $\varphi_V^{(\ell)}$ are $L^2$-normalized and since the volume of the fundamental domain satisfies $|\Gamma_0(q) \backslash G|  = q^{1+o(1)}$, we expect that for typical  $g \in G$ and $n \in {\mathbb Z}\setminus\{0\}$
\begin{align*}
  |\varphi_V^{(\ell)}(g)| = q^{-1/2+o(1)}, \quad \quad |\varrho_V(n) |   = q^{-1/2+o(1)}.
\end{align*}

With the help of Selberg's trace formula one can show that the eigenvalues $\nu_V$ in the cuspidal spectrum satisfy
\begin{align*}
    |\{ \nu_V \in i{\mathbb R}: |\nu_V| \leq K \}| = q^{1+o(1)} K^2,
\end{align*}
that is, there are roughly $q^{1+o(1)} K$ spectral parameters in $i[K,K+1]$.

To prove (3), for $\nu=(k-1)/2$ and $\sigma\ell\geq k$ we have
\begin{align*}
 \bigg(\pi^{-2 \nu_V}\frac{\Gamma(|\ell|/2+k/2)}{\Gamma(|\ell|/2-k/2+1)} & \bigg)^{1/2}   \mathcal{A}^\sigma  \phi_{\ell}(\mathrm{a}[y],\nu) \\
 =&  (-1)^{k/2} \pi^{1/2}\frac{\Gamma(|\ell|/2 - k/2 +1)^{1/2}}{\Gamma(|\ell|/2 + k/2)^{1/2}} e^{-2 \pi y} (4 \pi y)^{k/2} L^{(k-1)}_{(|\ell| - k)/2} (4 \pi y),
\end{align*}
where $L^{(\alpha)}_n$ is the Laguerre polynomial \cite[Chapter V (5.1.5)]{szegobook} defined by
\begin{align*}
 L^{(\alpha)}_n(x) :=  \frac{x^{-\alpha} e^{x}}{n!} \partial_{x}^{n} \bigg( e^{-x} x^{n+\alpha} \bigg).
\end{align*}
This can be seen from shifting the contour to $\operatorname{Im} (\xi) = -\infty$ in \eqref{eq:Jacquetintegral} and calculating the residue of the pole of order $(|\ell| - k)/2$ at $\xi = -i$. The Laguerre polynomials satisfy the orthogonality relation \cite[Chapter V, (5.1.1)]{szegobook}
\begin{align*}
    \int_0^\infty x^\alpha e^{-x} L^{(\alpha)}_{n}(x)L^{(\alpha)}_{m}(x) \mathrm d x = \mathbf{1}_{m=n} \frac{\Gamma(n+\alpha+1)}{\Gamma(n+1)}.
\end{align*}
We also have the recurrence relation \cite[Chapter V, (5.1.13)]{szegobook}
\begin{align*}
    L_{n}^{(\alpha)}(x) = \sum_{i=0}^{n}  L_{i}^{(\alpha-1)}(x).
\end{align*}
Thus, we get by expanding the square and by orthogonality
\begin{align*}
     \int_0^\infty x^{\alpha-1} e^{-x} L^{(\alpha)}_{n}(x)^2 \mathrm d x = \sum_{i=0}^n \frac{\Gamma(i+\alpha)}{\Gamma(i+1)}  \leq (n+1) \frac{\Gamma(n+\alpha)}{\Gamma(n+1)},
\end{align*}
so that in particular
\begin{align*}
        \int_0^\infty (4 \pi y)^{k-2} e^{-4 \pi y} L^{(k-1)}_{(|\ell| - k)/2}(4 \pi y)^2 \mathrm d y \ll  (|\ell|/2-k/2 +1 ) \frac{\Gamma(|\ell|/2 +k/2-1)}{\Gamma(|\ell|/2-k/2 +1)}.
\end{align*}
Thus, we have
\begin{align*}
  \pi^{-2 \nu_V}\frac{\Gamma(|\ell|/2+k/2)}{\Gamma(|\ell|/2-k/2+1)}  &\int_0^\infty  |\mathcal{A}^\sigma  \phi_{\ell}(\mathrm{a}[y],\nu) |^2 \frac{\mathrm d y}{y^2} \\
  =&  4^2\pi^3  \frac{\Gamma(|\ell|/2-k/2+1)}{\Gamma(|\ell|/2+k/2)} \int_0^\infty (4 \pi y)^{k-2} e^{-4 \pi y} L^{(k-1)}_{(|\ell| - k)/2}(4 \pi y)^2 \mathrm d y \\
\ll &\, (|\ell|/2-k/2 +1 )  \frac{\Gamma(|\ell|/2-k/2+1)}{\Gamma(|\ell|/2+k/2)}  \frac{\Gamma(|\ell|/2 +k/2-1)}{\Gamma(|\ell|/2-k/2 +1)} \\
\ll & \, 1.
\end{align*}

Let us first consider \eqref{eq:JIPMaas}.
    Let \begin{align*}
        \psi_{\nu,\ell}(t) := t^{-1/2} \langle F, \mathcal{A}^{\sigma} \phi_\ell(\mathrm{a}[t] \cdot,\nu) \rangle_{G}
    \end{align*}
    so that the left-hand side of \eqref{eq:JIPMaas} is
    \begin{align*}
     \sum_{\substack{V \in \mathcal{B}(q,\chi) \\ \operatorname{Re}(\nu_V) < 1/2}} \sum_{\ell \equiv \kappa \pmod{2}}  \sum_{n > 0} 
\psi_{\nu_V,\ell}(n) a_{V,\ell}(n).
    \end{align*}
We define the second order differential operator
\begin{align*}
    \Xi:= 1+\delta^2(1/4-\Omega) + \bigg( \frac{\delta X}{2 \pi i} \partial_x\bigg)^2 +  \bigg( \frac{\delta }{ i} \partial_\theta\bigg)^2
\end{align*}
and observe that  by \eqref{eq:Jacdiffop} and by left-invariance of $\Omega$  for any $J\geq 0$
\begin{align} \Xi^J   \mathcal{A}^{\sigma} \phi_\ell(\mathrm{a}[t] g,\nu) = \Xi^J l_{\mathrm{a}[t]}  \mathcal{A}^{\sigma} \phi_\ell( g,\nu)  = (1+(\delta \nu)^2 + (\delta t X)^2 + (\delta\ell)^2)^J l_{\mathrm{a}[t]}\mathcal{A}^{\sigma} \phi_\ell( g,\nu)  
\end{align}
and that by \eqref{eq:JIPderivbound} 
\begin{align} \begin{split}
         \Xi^J F \ll_J (1 +Y/X)^{2J} \quad \quad \text{and} \\
 \partial_t l_{\mathrm{a}[t^{-1}]}  \Xi^J F \ll_J (\delta t^2)^{-1} (1 +Y/X)^{2J}.
     \end{split} 
\end{align}
By \eqref{eq:xiJbound} we get for any $J\geq 0$
\begin{align*}
    \psi_{\nu,\ell}'(t) &= (t^{-1/2} \partial_t- \tfrac{1}{2} t^{-3/2}) \langle F, l_{\mathrm{a}[t]}\mathcal{A}^{\sigma} \phi_\ell( \cdot,\nu) \rangle_{G} \\
    &= \frac{(t^{-1/2} \partial_t- \tfrac{1}{2} t^{-3/2})}{(1+(\delta \nu)^2 + (\delta t X)^2 + (\delta\ell)^2)^J } \langle F, \Xi^J l_{\mathrm{a}[t]}\mathcal{A}^{\sigma} \phi_\ell( \cdot,\nu) \rangle_{G} \\
    &=  \frac{(t^{-1/2} \partial_t- \tfrac{1}{2} t^{-3/2})}{(1+(\delta \nu)^2 + (\delta t X)^2 + (\delta\ell)^2)^J } \langle  l_{\mathrm{a}[-t]}\overline{\Xi^J} F,  \mathcal{A}^{\sigma} \phi_\ell( \cdot,\nu) \rangle_{G},
 \end{align*}
where we used the symmetry of $\Omega$ \eqref{eq:omegaselfadjoint} as well as the Iwasawa decomposition to apply integration by parts for $\partial_x$ and $\partial_\theta$, and the invariance of the measure $\mathrm d g$. Using \eqref{eq:xi0bound} we get
\begin{align*}
