u)=\mathcal{M}\mathcal{A} k_{\ell,\ell} (\overline{
u}). \end{align*}

Recall $\phi_\ell( \mathrm{a}[y] \mathrm{n}[x] \mathrm{k}[	heta]) =\phi_\ell( \mathrm{n}[xy]\mathrm{a}[y] \mathrm{k}[	heta]) =y^{1/2+
u}e^{i \ell 	heta}$ so that by \eqref{eq:integrationonG}  egin{align*} \Phi_{\ell,\ell}(k;
u) =& \int_G k_{\ell,\ell}(h) \overline{\phi_{\ell}(h,
