For $f_1,f_2 \in L^2(G)$ define the convolution
\begin{align*}
    f_1 \ast f_2 (h) := \int_G f_1( g^{-1} h) f_2 ( g ) dg =  \int_G f_1(g^{-1} ) f_2 (h g ) \mathrm d g .
\end{align*}

For functions  $f_1,f_2 \in L^2(\mathrm{A})$ we define the convolution via
\begin{align*}
   f_1 \ast_{\mathrm{A}} f_2 (\mathrm{a}) := \int_{\mathrm{A}} f_1(\mathrm{a}_0^{-1} \mathrm{a}) f_2(\mathrm{a}_0)  \mathrm d \mathrm{a}_0.
\end{align*}

We have for $\mathrm{a}= \mathrm{a}[y]$
    \begin{align*}
  y^{-1/2}   \mathcal{A}(   f_1 \ast f_2 ) (\mathrm{a}) =& \int_\mathrm{N} ( f_1 \ast f_2)(\mathrm{a} \mathrm{n}) \mathrm d \mathrm{n} \\
    =&  \int_\mathrm{N} \int_G f_1(g^{-1} \mathrm{a} \mathrm{n}) f_2 ( g ) \mathrm d g \mathrm d \mathrm{n} \\
    =& \int_\mathrm{N} \int_G f_1(g^{-1}  \mathrm{n}) f_2 (\mathrm{a} g ) \mathrm d g \mathrm d \mathrm{n}. 
    \end{align*}

Using the Iwasawa decomposition $g=\mathrm{a}_0 \mathrm{n}_0 \mathrm{k}_0$ and the type assumption we get (denoting $\mathrm{a}_0=\mathrm{a}[y_0]$)
    \begin{align*}
       y^{-1/2}   \mathcal{A}(   f_1 \ast f_2 ) (\mathrm{a})&=  \int_\mathrm{N} \int_\mathrm{A} \int_\mathrm{N}  \int_\mathrm{K}   f_1(\mathrm{k}_0^{-1 }\mathrm{n_0}^{-1} \mathrm{a_0}^{-1}  \mathrm{n}) f_2 (\mathrm{a} \mathrm{a_0} \mathrm{n_0} \mathrm{k}_0)\mathrm d \mathrm{k}_0 \mathrm d \mathrm{n}_0 \mathrm d \mathrm{a_0} 
 \mathrm d \mathrm{n} \\ &=   \int_\mathrm{N} \int_\mathrm{A} \int_\mathrm{N}  f_1(\mathrm{n_0}^{-1} \mathrm{a_0}^{-1}  \mathrm{n}) f_2 (\mathrm{a} \mathrm{a_0} \mathrm{n_0} ) \mathrm d \mathrm{n}_0 \mathrm d \mathrm{a_0} 
 \mathrm d \mathrm{n}  \\
 &=\int_\mathrm{N} \int_\mathrm{A} \int_\mathrm{N} y_0^{-1}  f_1( \mathrm{n_0}^{-1}  \mathrm{n}\mathrm{a_0}^{-1} ) f_2 (\mathrm{a} \mathrm{a_0} \mathrm{n_0} ) \mathrm d \mathrm{n}_0 \mathrm d \mathrm{a_0} 
 \mathrm d \mathrm{n} \\
 &=\int_\mathrm{N} \int_\mathrm{A} \int_\mathrm{N} y_0^{-1} f_1( \mathrm{n} \mathrm{a_0}^{-1} ) f_2 (\mathrm{a} \mathrm{a_0} \mathrm{n_0} ) \mathrm d \mathrm{n}_0 \mathrm d \mathrm{a_0}  \mathrm d \mathrm{n}\\
 &=\int_\mathrm{N} \int_\mathrm{A} \int_\mathrm{N} f_1( \mathrm{a_0}^{-1}\mathrm{n}  ) f_2 (\mathrm{a} \mathrm{a_0} \mathrm{n_0} ) \mathrm d \mathrm{n}_0 \mathrm d \mathrm{a_0}  \mathrm d \mathrm{n} \\
 &=\int_\mathrm{N} \int_\mathrm{A} \int_\mathrm{N}  f_1( \mathrm{a_0}^{-1} \mathrm{a}  \mathrm{n}) f_2 (\mathrm{a_0} \mathrm{n_0} ) \mathrm d \mathrm{n}_0 \mathrm d \mathrm{a_0}  \mathrm d \mathrm{n}.
    \end{align*}

Thus, we have
\begin{align*}
    \mathcal{A}(   f_1 \ast f_2 ) (\mathrm{a}) =  &\int_\mathrm{A} y^{1/2} \int_\mathrm{N}  f_1( \mathrm{a_0}^{-1} \mathrm{a}  \mathrm{n}) \mathrm d \mathrm{n} \int_\mathrm{N}   f_2 (\mathrm{a_0} \mathrm{n_0} ) \mathrm d \mathrm{n}_0 \mathrm d \mathrm{a_0} \\
    =&   \int_\mathrm{A} \bigg((y/y_0)^{1/2}\int_\mathrm{N}  f_1( \mathrm{a_0}^{-1} \mathrm{a}  \mathrm{n}) \mathrm d \mathrm{n} \bigg)  \bigg(y_0^{1/2}\int_\mathrm{N}   f_2 (\mathrm{a_0} \mathrm{n_0} ) \mathrm d \mathrm{n}_0 \bigg)\mathrm d \mathrm{a_0} \\
= & \mathcal{A} f_1 \ast_{\mathrm{A}} \mathcal{A} f_2 (\mathrm{a}).  
\end{align*}

By $k_0(\mathrm{k} g \mathrm{k}^{-1})= k_0(g)$ we have  egin{align*} k_0(g) = \sum_{\ell \in {\mathbb Z}} k_{0,\ell,\ell}(g) , \quad k(g) = \sum_{\ell \in {\mathbb Z}} k_{0,\ell,\ell} \ast k_{0,\ell,\ell}(g), \end{align*} since for $\ell
eq \ell'$ we have by Cartan decomposition $k_{0,\ell',\ell'} \ast k_{0,\ell,\ell}\equiv 0$. Hence, we have $k_{\ell,\ell} =k_{0,\ell,\ell} \ast k_{0,\ell,\ell} $ and by Lemmas ef{le:mellinabel} and ef{le:abelconvo} we get  egin{align*} \Phi_{\ell,\ell}(k,
u) = \mathcal{M} \mathcal{A} (k_{0,\ell,\ell} \ast k_{0,\ell,\ell}) (\overline{
u}) = \mathcal{M} (\mathcal{A} k_{0,\ell,\ell} \ast_\mathrm{A} \mathcal{A} k_{0,\ell,\ell})) (\overline{
u}) = (\mathcal{M} \mathcal{A} k_{0,\ell,\ell} (\overline{
u}) )^2, \end{align*} where $\mathcal{M} \mathcal{A} k_{0,\ell,\ell} (\overline{
u})=\mathcal{M} \mathcal{A} k_{0,\ell,\ell} (
u)$ is real valued by the assumption that $k_0(g^{-1})=k_0(g)$.

By \eqref{eq:cartanAbel} we have for $y= e^t$
    \begin{align*}
    1 \leq  \cosh t  \leq   \cosh t + e^{t} x^2  /2 =  \cosh \varrho  \leq 1+O(1/K^2).
    \end{align*}

We construct a smooth compactly supported function $k:G\to{\mathbb C}$ such that $ \Phi_{\ell,\ell}(k,\nu)$ takes non-negative real values and
 \begin{align*}
      \Phi_{\ell,\ell}(k,\nu) \geq \mathbf{1}_{|\nu| \leq K} \mathbf{1}_{|\ell| \leq L}.
 \end{align*}

We let $C>0$ denote a large constant and choose
 \begin{align*}
     k_0(g) :=  C^4 K^2 L f(\varrho)  F(\varphi + \vartheta), \quad g = \mathrm{k}[\varphi]\mathrm{a}[e^{-\varrho}] \mathrm{k}[\vartheta],
 \end{align*}
where $f:{\mathbb R} \to [0,1]$ is a smooth even function with
\begin{align*}
   f(x)&=1, \, x \in  [-(2CK)^{-1},(2CK)^{-1}],\quad  \mathrm{supp}(f) \subseteq  [-(CK)^{-1},(CK)^{-1}],
\end{align*}
and $F:{\mathbb R} \to [0,1]$ is a $2\pi$-periodic even function with
\begin{align*}
       F(x)&=1, \, x \in  [-(2CL)^{-1},(2CL)^{-1}], \\
        F(x+\pi)&=(-1)^\kappa F(x),  \\
       \mathrm{supp}(F) &\subseteq [-(CL)^{-1},(CL)^{-1}] \cup \bigg(\pi + [-(CL)^{-1},(CL)^{-1}]\bigg).
\end{align*}

Then 
\begin{align*}
    k_{0,\ell,\ell}(g) = C^4 K^2 L \widehat{F}(\ell) e^{i\ell (\varphi + \vartheta)} f(\varrho), \quad \quad  \widehat{F}(\ell) = \frac{1}{2\pi}\int_{-\pi}^{\pi} F(\theta) e^{-i\ell \theta} \mathrm d \theta.
\end{align*}
By Taylor approximation we have for $|\ell| \leq L$ with $\ell \equiv \kappa \pmod{2}$
\begin{align*}
    \widehat{F}(\ell) &= \frac{1}{2\pi}\int_{-\pi}^{\pi} F(\theta) e^{-i\ell \theta} \mathrm d \theta =   \frac{1}{\pi}\int_{-(CL)^{-1}}^{(CL)^{-1}} F(\theta) (1+O( L \theta )) \mathrm d \theta   \\&=  \frac{1}{\pi}\int_{-(CL)^{-1}}^{(CL)^{-1}} F(\theta) (1+O( 1/C )) \mathrm d \theta  
    \geq  \frac{1}{\pi}\int_{-(2CL)^{-1}}^{(2CL)^{-1}} 1 \mathrm d \theta + O(C^{-2} L^{-1})  \geq (4C L)^{-1}
\end{align*}
if $C$ is sufficiently large. Furthermore, $  \widehat{F}(\ell) = 0$ for $\ell \not \equiv \kappa \pmod{2}$.

Similarly, for  $|\varrho| \leq (CK)^{-1}$ with $\mathrm{a}[e^t] \mathrm{n}[x] = \mathrm{k}_1 \mathrm{a}[e^{-\varrho}] \mathrm{k}_2$, $y=e^t$, we have by Lemma \ref{le:yvsvarrho} that for sufficiently large $C$
\begin{align*}
    \max\{ |t|, |x| \} \leq (C^{3/4} K)^{-1}.
\end{align*}
Therefore, for $|\nu| \leq K$ we get by Taylor approximation
\begin{align*}
    \int_{A}\int_N f(\varrho) y^{1/2+\nu} \mathrm d \mathrm{n} \mathrm d \mathrm{a}&=    \int_{{\mathbb R}}\int_{\mathbb R} f(\varrho) e^{t(1/2+\nu)} \mathrm d x \mathrm d t \\
    &=  \int_{-(C^{3/4}K)^{-1} }^{(C^{3/4}K)^{-1} }\int_{-(C^{3/4}K)^{-1} }^{(C^{3/4}K)^{-1} }f(\varrho) e^{t(1/2+\nu)} \mathrm d x \mathrm d t \\
    &=\int_{-(C^{3/4}K)^{-1} }^{(C^{3/4}K)^{-1} }\int_{-(C^{3/4}K)^{-1} }^{(C^{3/4}K)^{-1} }f(\varrho) (1+O(C^{-3/4})) \mathrm d x \mathrm d t \\
    & \geq \int_{-(C^{3/4}K)^{-1} }^{(C^{3/4}K)^{-1} }\int_{-(C^{3/4}K)^{-1} }^{(C^{3/4}K)^{-1} } \mathbf{1}_{|\varrho| \leq (2CK)^{-1}}  \mathrm d x \mathrm d t + O(C^{-9/4} K^{-2}) \\
    & \gg (CK)^{-2},
\end{align*}
where the last bound holds for $C$ sufficiently large.

Combining the above, we have for $|\ell| \leq L, |\nu| \leq K$ that
\begin{align*}
    \Phi_{\ell,\ell}(k_0,\nu)=C^4 K^2 L \widehat{F}(l)\int_{A}\int_N f(\varrho) y^{1/2+\nu} \mathrm d \mathrm{n} \mathrm d \mathrm{a}  \geq C^{1/2} \geq 1,
\end{align*}
 if we, once more, assume that $C$ is sufficiently large.

It remains to show that
\begin{align*}
    k(g) \ll \mathbf{1}_{|a|+|b|+|c|+|d| \leq 6}.
\end{align*}

Denoting $g= \mathrm{k}[\varphi] \mathrm{a}[e^{-\varrho}] \mathrm{k}[\vartheta], h= \mathrm{k}[\varphi_0] \mathrm{a}[e^{-\varrho_0}] \mathrm{k}[\vartheta_0],$ $k_1(g)=f(\varrho) F(\varphi+\vartheta)$, we have
 \begin{align*}
     k(g) &= (k_0 \ast k_0) (g) = C^8 K^{4} L^2 \int_G k_1(h^{-1} g) k_1(h) \mathrm d h \\
     &\leq  C^8 K^{4} L^2\int_G f(h^{-1} g) k_1(h) \mathrm d h 
     \\
     &\ll  C^8 K^{4} L^2 \int_{K \times  K} \int_{{\mathbb R}_{>0}} f(\varrho') F(\varphi_0 + \vartheta_0 ) f(\varrho_0) \sinh(\varrho_0)\mathrm d \varrho_0\mathrm d \mathrm{k}[\varphi_0 ]  \mathrm d \mathrm{k}[\vartheta_0 ] \\
    & \ll C^7 K^{4} L \int_{K} \int_{{\mathbb R}_{>0}} f(\varrho')  f(\varrho_0) \sinh(\varrho_0)\mathrm d \varrho_0\mathrm d \mathrm{k}[\varphi_0 ] , 
 \end{align*}
 where for some $\mathrm{k}_1,\mathrm{k}_1',\mathrm{k}_2'$ we have 
 \begin{align*}
     \mathrm{k}_1' \mathrm{a}[e^{-\varrho}] \mathrm{k}_2' = \mathrm{a}[e^{-\varrho_0}]\mathrm{k}_1 \mathrm{a}[e^{-\varrho'}].
 \end{align*}
 Here $\varrho_0,\varrho'$ are supported on $[-(CK)^{-1},(CK)^{-1}]$ and 
 \begin{align*}
     \cosh(\varrho) &= 1+ 2u( \mathrm{a}[e^{-\varrho_0}]\mathrm{k}_1 \mathrm{a}[e^{-\varrho'}] i,i) = 1+ 2u( \mathrm{k}_1 \mathrm{a}[e^{-\varrho'}] i,\mathrm{a}[e^{\varrho_0}]i) \\
     &= 1+ 2u( \mathrm{k}_1  e^{-\varrho'}i, e^{\varrho_0}i) =  1+ 2u( i+ O((CK)^{-1}), i+ O((CK)^{-1})) \\
     & = 1+ O((CK)^{-2}),
 \end{align*}
which implies that $k(g)$ is supported on $|\varrho| \ll (CK)^{-1}$.
Therefore, using $\sinh(\varrho_0) \ll |\varrho_0|$ we get
 \begin{align*}
      k(g) \ll C^5 K^2 L \mathbf{1}_{|\varrho| \ll (CK)^{-1}}.
 \end{align*}
Taking $C$ sufficiently large this is by \eqref{eq:ulowerbound} supported on $a^2+b^2+c^2+d^2 \leq 2+1/100$ which implies  $|a| + |b| +|c| +|d| \leq 6$ since $4 \cdot \sqrt{2+1/100} < 6$.

For $V \in \mathcal{B}(q,\chi)$, $t >0$, and coefficients $\beta_h$ we denote
