 Indeed, denoting $(a,c,d)=(\phi_1(x,\theta,y),\phi_2(x,\theta,y),\phi_3(x,\theta,y))$, using \eqref{eq:iwasawatomatrix} we compute for any $J_1+J_2+J_3 \leq 2J+1$
\begin{align*}
      \partial_x^{J_1} \partial_y^{J_2}  \partial_\theta^{J_3} F(\mathrm{n}[x]\mathrm{a}[y]\mathrm{k}[\theta]) = &\bigg(\frac{\partial \phi_1}{\partial x} \partial_a +\frac{\partial \phi_2}{\partial x} \partial_c +\frac{\partial \phi_3}{\partial x} \partial_d \bigg)^{J_1} \bigg(\frac{\partial \phi_1}{\partial y} \partial_a +\frac{\partial \phi_2}{\partial y} \partial_c +\frac{\partial \phi_3}{\partial y} \partial_d \bigg)^{J_2}  \\
      & \times \bigg(\frac{\partial \phi_1}{\partial \theta} \partial_a +\frac{\partial \phi_2}{\partial  \theta} \partial_c +\frac{\partial \phi_3}{\partial  \theta} \partial_d \bigg)^{J_3}f(a,c,d) \\
      \ll_{J_1,J_2,J_3} & \delta^{-J_1}\bigg(  \frac{1}{Y^{1/2}   A }\bigg)^{J_1} \delta^{-J_2}\bigg(\frac{1}{Y^{1/2}  A} + \frac{X}{Y^{3/2} A } + \frac{1}{Y^{3/2} C} +\frac{1}{Y^{3/2} D}\bigg)^{J_2} \\
      & \times \delta^{-J_3}\bigg( \frac{Y^{1/2}}{A} + \frac{X}{Y^{1/2} A} + \frac{1}{Y^{1/2} C} + \frac{1}{Y^{1/2} D} \bigg)^{J_3}
      \\ 
      \ll_{J_1,J_2,J_3} &\delta^{-J_1} \bigg( \frac{C}{A} \bigg)^{J_1} \delta^{-J_2}\bigg( \frac{C}{A} + CD \bigg)^{J_2}  \delta^{-J_3}\bigg( 1 + \frac{1}{AD} \bigg)^{J_3}
      \\
     \ll_{J_1,J_2,J_3} & (\delta_1  X)^{-J_1} (\delta_1 Y)^{-J_2} (\delta_1)^{-J_3},
\end{align*}
making use of $C =D$ and denoting $\delta_1 := \min \{\delta,\delta AD \}$. Note also $Y/X \leq 1$.




We now apply spectral expansion for $P_{f}$. By Proposition \ref{prop:specdecompL2} we have
\begin{align*}
    \nonumber P_{f}(g)=& \mathbf{1}_{\chi \,\mathrm{principal}}\frac{1}{|\Gamma \backslash G|} \langle P_{f} ,1 \rangle_{\Gamma \backslash G} +\sum_{V\in \mathcal{B}(q,\chi)} \sum_{\ell \equiv \kappa \pmod{2}}\langle P_{f} ,\varphi_V^{(\ell)} \rangle_{\Gamma \backslash G}  \varphi_V^{(\ell)}(g)\\
        &+\sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)} \sum_{\ell \equiv \kappa \pmod{2}} \frac{1}{4 \pi i} \int_{(0)} \langle P_{f}, E^{(\ell)}_{\mathfrak{c}}(\cdot,\nu) \rangle_{\Gamma \backslash G}  E^{(\ell)}_{\mathfrak{c}}(g,\nu) \mathrm d \nu.
\end{align*}
Therefore, we get
\begin{align} \begin{split}
    S_{f,\alpha,\beta,\chi}(\Gamma,T)=& \sum_{\tau \in T}  \sum_{\gcd(h,q)=1} \alpha(\tau) \frac{\beta_h \sigma_1(h)}{\sqrt{h}} \mathbf{1}_{\chi \,\mathrm{principal}}\frac{1}{|\Gamma \backslash G|} \langle P_{f} ,1\rangle_{\Gamma \backslash G}+\mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)\\
    &+\mathcal{E}_{f,\alpha,\beta,\chi}(\Gamma,T),
    \end{split}
\end{align}
where by the action of the Hecke operators as in \eqref{eq:heckecusp} the cuspidal spectrum contribution is
\begin{align} \mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)=\sum_{V\in \mathcal{B}(q,\chi)}\sum_{\gcd(h,q)=1}\beta_h\lambda_V(h) \sum_{\ell \equiv \kappa \pmod{2}}\langle P_{f} ,\varphi_V^{(\ell)} \rangle_{\Gamma \backslash G} \sum_{\tau\in T}\alpha(\tau) \varphi_V^{(\ell)}(\tau)
\end{align}
and similarly by \eqref{eq:heckeeis} the continuous spectrum contribution is
\begin{align} \mathcal{E}_{f,\alpha,\beta,\chi}(\Gamma,T)=\frac{1}{4\pi i}\sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)}\int_{(0)}  \sum_{\gcd(h,q)=1}\beta_h \lambda_{\mathfrak{c},\nu}(h) \sum_{\ell \equiv \kappa \pmod{2}} \langle P_{f}, E^{(\ell)}_{\mathfrak{c}}(\cdot,\nu) \rangle_{\Gamma \backslash G}  \sum_{\tau\in T}\alpha(\tau) E^{(\ell)}_{\mathfrak{c}}(\tau,\nu) \mathrm d \nu.
\end{align}

\subsubsection{Main term}
The projection onto the constant function in \eqref{eq:Pf0specdecomp} gives the main term in \eqref{eq:GBB,M}. Indeed, for $\chi$ principal we have by unfolding
\begin{align*}
    \langle P_{f} ,1 \rangle_{\Gamma \backslash G}&=\sum_{\gamma \in \Gamma} \int_{\Gamma \backslash G} F(\gamma g) \mathrm d g= \int_{ G} F(g) \mathrm d g.
\end{align*}
 Thus, using the fact that the Hecke operator runs over $\sum_{d|h}\sum_{b  \pmod{d}} 1=\sigma_1(h)$ many points, we get
\begin{align*}
   \sum_{\tau \in T}  \sum_{\gcd(h,q)=1} \alpha(\tau) \frac{\beta_h \sigma_1(h)}{\sqrt{h}} \mathbf{1}_{\chi \,\mathrm{principal}}\frac{1}{|\Gamma \backslash G|} \langle P_{f}(\tau) ,1\rangle&= M_{f,\alpha,\beta,\chi}(\Gamma,T).
\end{align*}
Consequently, the proof of Theorem \ref{thm:Gmainblackbox} is reduced to estimating $\mathcal{C}_{f,\alpha,\beta}(\Gamma,T)$ and $\mathcal{E}_{f,\alpha,\beta}(\Gamma,T)$.





\subsubsection{Cuspidal Spectrum}
We now estimate $\mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)$ as given by \eqref{eq:specdecompcusp}. Unfolding gives for the projections
\begin{align*}
    \langle P_{f} ,\varphi_V^{(\ell)} \rangle_{\Gamma \backslash G} &=\sum_{\gamma \in \Gamma} \int_{\Gamma \backslash G} \overline{\chi}(\gamma) F(\gamma g) \overline{\varphi_V^{(\ell)}(g)}  \mathrm d g =\int_{G} F( g) \overline{\varphi_V^{(\ell)}(g)}  \mathrm d g.
\end{align*}
We plug in the Fourier series expansion of Proposition \ref{prop:fourierexpansionbasis} to get
\begin{align*}
    &\int_{G} F( g) \overline{\varphi_V^{(\ell)}(g)}  \mathrm d g\\
    =&\left|\pi^{-2\nu_V}\frac{\Gamma(|\ell|+\nu_V+1/2)}{\Gamma(|\ell|-\nu_V+1/2)} \right|^{1/2}\sum_{n\neq 0} \frac{\overline{\varrho_V(n)}}{\sqrt{|n|}}  \int_{G} F( g)  \overline{\mathcal{A}^{\operatorname{sgn}(n)}\phi_{\ell}(\mathrm{a}[|n|]g,\nu_V)}\mathrm d g.
\end{align*}
We now apply Proposition \ref{prop:Jacquetinnerproduct}. More precisely, for $V$ in the regular and exceptional spectrum (that is $\operatorname{Re}(\nu_V)<1/2$), we observe that 
\begin{align*}
\left|\pi^{-2\nu_V}\frac{\Gamma(|\ell|+\nu_V+1/2)}{\Gamma(|\ell|-\nu_V+1/2)} \right|^{1/2}\ll 1
\end{align*}
and apply \eqref{eq:JIPMaas}. For the remaining part of the cuspidal spectrum, that is for $V$ in the discrete series, we apply \eqref{eq:JIPHolom}. Hence, denoting
\begin{align*}
    a_{V,\ell}(  n) :=  \overline{\varrho_V(\sigma n)} \sum_{\gcd(h,q)=1} \beta_h \lambda_V(h) \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau),
\end{align*}
we obtain (with $D_J(t,\nu_V,\ell)$ as in \eqref{eq:decaydef})
\begin{align*}
\mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)   \ll_{\varepsilon,J}     \max_{t>0}  \frac{Z^\varepsilon X}{Y^{1/2}} \sum_{\substack{V\in \mathcal{B}(q,\chi) \\  }} \sum_{\ell \equiv \kappa \pmod{2}} &(1+\mathbf{1}_{\operatorname{Re}(\nu_V) < 1/2}(  Yt  )^{- \operatorname{Re}(\nu_V)} ) D_J(t,\nu_V,\ell)
\\ & \times \bigg| \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau)\bigg| |R_V(t,\beta)|.
\end{align*}
 By using $Y=\frac{1}{CD}$, $X=1/N = \frac{AD+1}{CD}$ we get
\begin{align*}  \mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)   \ll_{\varepsilon,J}& \max_{t >0} \frac{Z^\varepsilon \delta^{1/2} \delta_1^{-1/2}(AD)^{1/2}}{N^{1/2}} \\
  &\times\sum_{\substack{V \in \mathcal{B}(q,\chi)  }} \sum_{\ell \equiv \kappa \pmod{2}}(1+\mathbf{1}_{\operatorname{Re}(\nu_V) < 1/2}( \tfrac{CD}{t}  )^{ \operatorname{Re}(\nu_V)})  D_J(t,\nu_V,\ell)  \\ & \times
\bigg| \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau)\bigg| |R_V(t,\beta)|. 
\end{align*}
We apply Cauchy-Schwarz in the form
\begin{align}\nonumber
    &\sum_{V,\ell}  \frac{D_J(t,\nu_V,\ell)}{N^{1/2}}\bigg| \sum_\tau \sum_h \sum_n \bigg| \\
    \leq& \bigg(  \sum_{V,\ell} D_J(t,\nu_V,\ell) (1+\log t)^2 \bigg| \sum_\tau \bigg|^2 \bigg)^{1/2} \bigg(  \sum_{V,\ell} \frac{D_J(t,\nu_V,\ell)}{N (1+\log t)^2} \bigg|  \sum_h \sum_n \bigg|^2  \bigg)^{1/2}.
\end{align}
Here $\sum_\ell \frac{D_J(t,\nu_V,\ell)}{(1+\log t)^2}  \ll \delta^{-O(1)} Z^\varepsilon E_J(t/N,\nu_V)$ so that the second factor is bounded by \begin{align*}
   \delta^{-O(1)} \mathcal{R}_{\Gamma,\beta}(X,N)^{1/2}.
\end{align*} 
Using Proposition \ref{prop:boundbykernel} the first factor is bounded by 
\begin{align*}
    &\ll_{\varepsilon,J} Z^\varepsilon \delta^{-O(1)}\bigg(\sum_{V,\ell} \min_{J_0\in \{0,1,\dots,J\}} \frac{1}{(1+|\delta \nu| + |\delta \ell|)^{2J_0-1}}  \bigg| \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau)\bigg| ^2\bigg)^{1/2} \\
   & \ll_\varepsilon Z^\varepsilon \delta^{-O(1)}\mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2},
\end{align*}
which converges for $J \geq 3$. Thus, we obtain
\begin{align*}
\mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)  \ll_{\varepsilon,J} Z^\varepsilon \delta^{-O(1)}   (AD)^{1/2} \, \mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2}\mathcal{R}_{\Gamma,\beta}(X,N)^{1/2}.
\end{align*}
\eqref{eq:Gmaintarget}.


\subsubsection{Eisenstein Series}
Similarly as above, we compute $\langle P_{f}, E^{(\ell)}_{\mathfrak{c}}(\cdot,\nu) \rangle_{\Gamma \backslash G} $ by unfolding. The contribution from $n \neq 0$ is bounded \emph{mutatis mutandis} as in the previous section. The contribution from $n= 0$ is
\begin{align*}
    \mathcal{E}_{f,\alpha,\beta,\chi,0}(\Gamma,T):=\frac{1}{4\pi i}\sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)}\int_{(0)}  \sum_{\ell \equiv \kappa \pmod{2}} \sum_{\gcd(h,q)=1}\beta_h \lambda_{\mathfrak{c},\nu}(h)  \langle F, E^{(\ell)}_{\mathfrak{c},0}(\cdot,\nu)\rangle_{ G}  \sum_{\tau\in T}\alpha(\tau) E^{(\ell)}_{\mathfrak{c}}(\tau,\nu) \mathrm d \nu
\end{align*}
where
\begin{align*}
   E^{(\ell)}_{\mathfrak{c},0}(g,\nu)  :=1_{\mathfrak{c}=\infty}\phi_\ell(g,\nu)+\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)\phi_\ell(g,-\nu).
\end{align*}
Using $|\lambda_{\mathfrak{c},\nu}(h) | \ll_\varepsilon h^\varepsilon$ and Proposition \ref{prop:eisenstein0prop} we get
\begin{align*}
\mathcal{E}_{f,\alpha,\beta,\chi,0}(\Gamma,T) \ll_{\varepsilon,J} \frac{Z^\varepsilon \|\beta\|_1 \delta^{1/2} \delta_1^{-1/2}(AD)^{1/2}}{N^{1/2}} \sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)}\int_{(0)}  \sum_{\ell \equiv \kappa \pmod{2}} D_J(1,\nu,\ell)  \\ 
\times \left( \mathbf{1}_{\mathfrak{c} = \infty} + |\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)|\right)
\bigg|\sum_{\tau\in T}\alpha(\tau) E^{(\ell)}_{\mathfrak{c}}(\tau,\nu)\bigg| |\mathrm d \nu|.
\end{align*}
We have
\begin{align*}
    |\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)| \leq& \mathbf{1}_{\mathfrak{c} = \infty}+|\mathbf{1}_{\mathfrak{c} = \infty}+\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)|   \\
    = &\mathbf{1}_{\mathfrak{c} = \infty} + \bigg| \int_0^1 E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu) \mathrm d x\bigg| \\
    \leq & \mathbf{1}_{\mathfrak{c} = \infty} +  \int_0^1 
 \bigg|E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu)\bigg| \mathrm d x.
\end{align*}
Thus, for some $x \in {\mathbb R}$ we have
\begin{align*}
\mathcal{E}_{f,\alpha,\beta,\chi,0}(\Gamma,T) \ll_{\varepsilon,J} \frac{Z^\varepsilon \|\beta\|_1 \delta^{1/2} \delta_1^{-1/2}(AD)^{1/2}}{N^{1/2}} \sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)}\int_{(0)}  \sum_{\ell \equiv \kappa \pmod{2}}D_J(1,\nu,\ell)  \\ 
\times  \left( \mathbf{1}_{\mathfrak{c} = \infty} +  \bigg|E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu)\bigg| \right)   \bigg|\sum_{\tau\in T}\alpha(\tau) E^{(\ell)}_{\mathfrak{c}}(\tau,\nu)\bigg| |\mathrm d \nu|
\end{align*}
The contribution from $\mathbf{1}_{\mathfrak{c} = \infty}$ is bounded by Cauchy-Schwarz and Proposition \ref{prop:boundbykernel} by
\begin{align*}
    \ll_{\varepsilon,J}  \frac{Z^\varepsilon \|\beta\|_1 \delta^{-O(1)}(AD)^{1/2}}{N^{1/2}} \mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2}.
\end{align*} 
The contribution from $\bigg|E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu)\bigg|$ is bounded by applying Cauchy-Schwarz and Proposition \ref{prop:boundbykernel} twice 
\begin{align*}
  \ll_{\varepsilon,J}  \frac{Z^\varepsilon \|\beta\|_1 \delta^{-O(1)}(AD)^{1/2}}{N^{1/2}} \mathcal{K}(\Gamma,\{\mathrm{n}[x]\})^{1/2}\mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2}  + Z^{-\varepsilon J},
\end{align*}
where
\begin{align*}
\mathcal{K}(\Gamma,\{\mathrm{n}[x]\})  \ll  \delta^{-O(1)} \sum_{\gamma \in \Gamma} k_1(\mathrm{n}[-x] \gamma \mathrm{n}[x]) \ll \delta^{-O(1)}
\end{align*}
by using $k_1(\smqty(a& b \\ c& d)) \leq \mathbf{1}_{|a|+|b|  +|c|+|d| \leq 6}.$  \qed

