and apply \eqref{eq:JIPMaas}. For the remaining part of the cuspidal spectrum, that is for $V$ in the discrete series, we apply \eqref{eq:JIPHolom}. Hence, denoting
\begin{align*}
    a_{V,\ell}(  n) :=  \overline{\varrho_V(\sigma n)} \sum_{\gcd(h,q)=1} \beta_h \lambda_V(h) \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau),
\end{align*}
we obtain (with $D_J(t,\nu_V,\ell)$ as in \eqref{eq:decaydef})
\begin{align*}
\mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)   \ll_{\varepsilon,J}     \max_{t>0}  \frac{Z^\varepsilon X}{Y^{1/2}} \sum_{\substack{V\in \mathcal{B}(q,\chi) \\  }} \sum_{\ell \equiv \kappa \pmod{2}} &(1+\mathbf{1}_{\operatorname{Re}(\nu_V) < 1/2}(  Yt  )^{- \operatorname{Re}(\nu_V)} ) D_J(t,\nu_V,\ell)
\\ & \times \bigg| \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau)\bigg| |R_V(t,\beta)|.
\end{align*}
 By using $Y=\frac{1}{CD}$, $X=1/N = \frac{AD+1}{CD}$ we get
\begin{align*}  \mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)   \ll_{\varepsilon,J}& \max_{t >0} \frac{Z^\varepsilon \delta^{1/2} \delta_1^{-1/2}(AD)^{1/2}}{N^{1/2}} \\
  &\times\sum_{\substack{V \in \mathcal{B}(q,\chi)  }} \sum_{\ell \equiv \kappa \pmod{2}}(1+\mathbf{1}_{\operatorname{Re}(\nu_V) < 1/2}( \tfrac{CD}{t}  )^{ \operatorname{Re}(\nu_V)})  D_J(t,\nu_V,\ell)  \\ & \times
\bigg| \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau)\bigg| |R_V(t,\beta)|. 
\end{align*}
We apply Cauchy-Schwarz in the form
\begin{align}\nonumber
    &\sum_{V,\ell}  \frac{D_J(t,\nu_V,\ell)}{N^{1/2}}\bigg| \sum_\tau \sum_h \sum_n \bigg| \\
    \leq& \bigg(  \sum_{V,\ell} D_J(t,\nu_V,\ell) (1+\log t)^2 \bigg| \sum_\tau \bigg|^2 \bigg)^{1/2} \bigg(  \sum_{V,\ell} \frac{D_J(t,\nu_V,\ell)}{N (1+\log t)^2} \bigg|  \sum_h \sum_n \bigg|^2  \bigg)^{1/2}.
\end{align}
Here $\sum_\ell \frac{D_J(t,\nu_V,\ell)}{(1+\log t)^2}  \ll \delta^{-O(1)} Z^\varepsilon E_J(t/N,\nu_V)$ so that the second factor is bounded by \begin{align*}
   \delta^{-O(1)} \mathcal{R}_{\Gamma,\beta}(X,N)^{1/2}.
\end{align*} 
Using Proposition \ref{prop:boundbykernel} the first factor is bounded by 
\begin{align*}
    &\ll_{\varepsilon,J} Z^\varepsilon \delta^{-O(1)}\bigg(\sum_{V,\ell} \min_{J_0\in \{0,1,\dots,J\}} \frac{1}{(1+|\delta \nu| + |\delta \ell|)^{2J_0-1}}  \bigg| \sum_{\tau \in T} \alpha(\tau) \varphi_V^{(\ell)}(\tau)\bigg| ^2\bigg)^{1/2} \\
   & \ll_\varepsilon Z^\varepsilon \delta^{-O(1)}\mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2},
\end{align*}
which converges for $J \geq 3$. Thus, we obtain
\begin{align*}
\mathcal{C}_{f,\alpha,\beta,\chi}(\Gamma,T)  \ll_{\varepsilon,J} Z^\varepsilon \delta^{-O(1)}   (AD)^{1/2} \, \mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2}\mathcal{R}_{\Gamma,\beta}(X,N)^{1/2}.
\end{align*}
\eqref{eq:Gmaintarget}.

Similarly as above, we compute $\langle P_{f}, E^{(\ell)}_{\mathfrak{c}}(\cdot,\nu) \rangle_{\Gamma \backslash G} $ by unfolding. The contribution from $n \neq 0$ is bounded \emph{mutatis mutandis} as in the previous section. The contribution from $n= 0$ is
\begin{align*}
    \mathcal{E}_{f,\alpha,\beta,\chi,0}(\Gamma,T):=\frac{1}{4\pi i}\sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)}\int_{(0)}  \sum_{\ell \equiv \kappa \pmod{2}} \sum_{\gcd(h,q)=1}\beta_h \lambda_{\mathfrak{c},\nu}(h)  \langle F, E^{(\ell)}_{\mathfrak{c},0}(\cdot,\nu)\rangle_{ G}  \sum_{\tau\in T}\alpha(\tau) E^{(\ell)}_{\mathfrak{c}}(\tau,\nu) \mathrm d \nu
\end{align*}
where
\begin{align*}
   E^{(\ell)}_{\mathfrak{c},0}(g,\nu)  :=1_{\mathfrak{c}=\infty}\phi_\ell(g,\nu)+\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)\phi_\ell(g,-\nu).
\end{align*}
Using $|\lambda_{\mathfrak{c},\nu}(h) | \ll_\varepsilon h^\varepsilon$ and Proposition \ref{prop:eisenstein0prop} we get
\begin{align*}
\mathcal{E}_{f,\alpha,\beta,\chi,0}(\Gamma,T) \ll_{\varepsilon,J} \frac{Z^\varepsilon \|\beta\|_1 \delta^{1/2} \delta_1^{-1/2}(AD)^{1/2}}{N^{1/2}} \sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)}\int_{(0)}  \sum_{\ell \equiv \kappa \pmod{2}} D_J(1,\nu,\ell)  \\ 
\times \left( \mathbf{1}_{\mathfrak{c} = \infty} + |\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)|\right)
\bigg|\sum_{\tau\in T}\alpha(\tau) E^{(\ell)}_{\mathfrak{c}}(\tau,\nu)\bigg| |\mathrm d \nu|.
\end{align*}
We have
\begin{align*}
    |\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)| \leq& \mathbf{1}_{\mathfrak{c} = \infty}+|\mathbf{1}_{\mathfrak{c} = \infty}+\varrho_{\mathfrak{c},\nu}^{(\ell)}(0)|   \\
    = &\mathbf{1}_{\mathfrak{c} = \infty} + \bigg| \int_0^1 E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu) \mathrm d x\bigg| \\
    \leq & \mathbf{1}_{\mathfrak{c} = \infty} +  \int_0^1 
 \bigg|E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu)\bigg| \mathrm d x.
\end{align*}
Thus, for some $x \in {\mathbb R}$ we have
\begin{align*}
\mathcal{E}_{f,\alpha,\beta,\chi,0}(\Gamma,T) \ll_{\varepsilon,J} \frac{Z^\varepsilon \|\beta\|_1 \delta^{1/2} \delta_1^{-1/2}(AD)^{1/2}}{N^{1/2}} \sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)}\int_{(0)}  \sum_{\ell \equiv \kappa \pmod{2}}D_J(1,\nu,\ell)  \\ 
\times  \left( \mathbf{1}_{\mathfrak{c} = \infty} +  \bigg|E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu)\bigg| \right)   \bigg|\sum_{\tau\in T}\alpha(\tau) E^{(\ell)}_{\mathfrak{c}}(\tau,\nu)\bigg| |\mathrm d \nu|
\end{align*}
The contribution from $\mathbf{1}_{\mathfrak{c} = \infty}$ is bounded by Cauchy-Schwarz and Proposition \ref{prop:boundbykernel} by
\begin{align*}
    \ll_{\varepsilon,J}  \frac{Z^\varepsilon \|\beta\|_1 \delta^{-O(1)}(AD)^{1/2}}{N^{1/2}} \mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2}.
\end{align*} 
The contribution from $\bigg|E^{(\ell)}_{\mathfrak{c}}(\mathrm{n}[x],\nu)\bigg|$ is bounded by applying Cauchy-Schwarz and Proposition \ref{prop:boundbykernel} twice 
\begin{align*}
  \ll_{\varepsilon,J}  \frac{Z^\varepsilon \|\beta\|_1 \delta^{-O(1)}(AD)^{1/2}}{N^{1/2}} \mathcal{K}(\Gamma,\{\mathrm{n}[x]\})^{1/2}\mathcal{K}_{f,\alpha}(\Gamma,T,1)^{1/2}  + Z^{-\varepsilon J},
\end{align*}
where
\begin{align*}
\mathcal{K}(\Gamma,\{\mathrm{n}[x]\})  \ll  \delta^{-O(1)} \sum_{\gamma \in \Gamma} k_1(\mathrm{n}[-x] \gamma \mathrm{n}[x]) \ll \delta^{-O(1)}
\end{align*}
by using $k_1(\smqty(a& b \\ c& d)) \leq \mathbf{1}_{|a|+|b|  +|c|+|d| \leq 6}.$  \qed

The second bound also follows from these propositions, after we combine the coefficients by using the multiplicativity relation for $\gcd(h,q)=1$
    \begin{align*}
        \lambda_V(h)\varrho_V(n) = \sum_{d|(h,n)} \chi(d)  \varrho_V(nh/d^2),
    \end{align*}
    so that we can apply the spectral large sieve with the weights
\begin{align*}
    \alpha_m=\sum_{n\leq N, h\sim H}\beta_h \sum_{\substack{d|(h,n)\\mathfrak{m}=nh/d^2}}\chi(d)=\sum_{d^2\leq NH/m}\chi(d) \sum_{h\sim H/d}\beta_{hd} \sum_{\substack{n\leq N/d\\ nh=m}}1.
\end{align*}

Recall that we want to evaluate
\begin{align*}
      S_{f,\alpha}(\mathcal{M}) = \sum_{g=\smqty(a & b \\mathfrak c& d) \in \mathcal{M}}  \alpha(g) f(a,c,d) ,
\end{align*}
where $\mathcal{M} \subseteq \operatorname{SL}_2({\mathbb R})$, $f$ satisfies the assumptions of Theorem \ref{thm:Gmainblackbox}, and
\begin{align*}
    L= C/D \quad \text{and} \quad N \frac{CD q_1}{AD+ 1} = \delta^{-O(1)} \frac{q_1 C}{A}.
\end{align*}
The claim then follows from Theorem \ref{thm:Gmainblackbox} ($h=1,\chi$ principal) and Corollary \ref{cor:Gmainblackbox} since by denoting $g= \tau_2^{-1} \gamma\tau_1$
\begin{align*}
    \mathcal{K}_{\alpha,\chi}(\Gamma,T,L)&=   \sum_{\tau_1, \tau_2 \in T} \alpha(\tau_1)  \overline{\alpha(\tau_2)}\sum_{\gamma \in \Gamma} k_L(\tau_2^{-1} \gamma\tau_1  ) \\
    & = \sum_{g \in \mathcal{M}^{-1}\mathcal{M}} k_L(\tau_2^{-1} \gamma\tau_1  )  \sum_{\substack{\tau_1, \tau_2 \in T \\ \tau_2 g \tau_1^{-1} \in \Gamma}} \alpha(\tau_1)  \overline{\alpha(\tau_2)}  \\
   & = \sum_{g \in \mathcal{M}^{-1}\mathcal{M}} k_L(\tau_2^{-1} \gamma\tau_1  )  \sum_{ \substack{\tau\in \Gamma \backslash \mathcal{M} 
 \\ \tau g \in \mathcal{M}}} \alpha(\tau) \overline{\alpha(\tau g)}  \\
    & \leq \sum_{\substack{g =\smqty(a & b \\mathfrak c & d) \in \mathcal{M}^{-1} \mathcal{M} \\  |a|+|b| L +|c|/L+|d| \leq 6}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash \mathcal{M} 
 \\ \tau g \in \mathcal{M}}} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr|.
\end{align*}
\qed

Define the projective line over ${\mathbb Z}/p^k {\mathbb Z}$ 
\begin{align*}
    \mathbb{P}_{p^k}^{1} := \{(x,y) \in ({\mathbb Z}/p^k {\mathbb Z})^2: x \, \text{or} \, y \in  ({\mathbb Z}/p^k {\mathbb Z})^{\times}\} / \sim,
\end{align*}
where we define an equivalence relation by $(x_1,y_1) \sim (x_2,y_2)$ if there exists $\lambda \in ({\mathbb Z}/p^k {\mathbb Z})^\times$ such that $(x_1,y_1) =  (\lambda x_2,\lambda y_2)$.

For $q \in {\mathbb Z}_{>0}$ we define
\begin{align*}
     \mathbb{P}_{q}^{1} := \prod_{p^k||q}  \mathbb{P}_{p^k}^{1}.
\end{align*}

Given $q_1,q_2$ we define then the projection 
\begin{align*}
    \pi_{q_1,q_2}: \operatorname{SL}_2({\mathbb Z}) \to  \mathbb{P}_{q_1}^{1} \times  \mathbb{P}_{q_2}^{1}:  \mqty(a & b \\ c &d) \mapsto ( \pi_{q_1}(a,b) ,\pi_{q_2}(c,d)).
\end{align*}

By symmetry we may restrict to the part $h,k \geq 1$ (otherwise we can multiply the determinant equation throughout by $-1$ and let $(c,d) \mapsto (-c,-d)$). Recall that
\begin{align*}
    \operatorname{M}_{2,h,k}({\mathbb Z}) = \bigg\{ \mqty(a &b \\ c &d) \in \operatorname{M}_{2,hk}({\mathbb Z}): \, \gcd(a,c,k)=\gcd(b,d,k)=1 \bigg\}.
\end{align*}
Note that the action from left by $\operatorname{SL}_2({\mathbb Z})$ preserves the conditions $\gcd(a,c,k)=\gcd(b,d,k)=1$ so that we may set 
\begin{align*}
  T_{h,k} := \operatorname{SL}_2({\mathbb Z}) \backslash   \operatorname{M}_{2,h,k}({\mathbb Z}).
\end{align*}
Recall that in the statement of Theorem \ref{thm:twisteddetwbound}  we denote $T = \Gamma \backslash \operatorname{SL}_2({\mathbb Z})$, $\Gamma=\Gamma_2(q_1,q_2)$, $q=q_1 q_2$. By definition
\begin{align*}
    \operatorname{M}_{2,h ,k}({\mathbb Z}) =  \operatorname{SL}_2({\mathbb Z})  T_{h,k} = \Gamma \, T \, T_{h,k}.
\end{align*}
Denote further
\begin{align*}
    T_{h}^{(q_1)} = \bigg\{ \mqty(a & bq_1 \\ & d): a,d \in {\mathbb Z}_{>0}, \quad ad = h, \quad b \pmod{d} \bigg\}.
\end{align*}
By $(h,kq) = 1$ we have
\begin{align} \operatorname{M}_{2,h, k}({\mathbb Z}) =   \Gamma \, T \,  T_{h}^{(q_1)} T_{1,k} =    \Gamma \, T_{h}^{(q_1)}\, T \,  T_{1,k}.
\end{align}
Indeed, to show that $\Gamma \, T \,  T_{h}^{(q_1)} = \Gamma \,T_{h}^{(q_1)} \, T  $ we note that for $\sigma_j \in T_{h}^{(q_1)}, \tau_j \in T$
\begin{align*}
    \Gamma \sigma_1 \tau_1 =   \Gamma \sigma_2 \tau_2 \Rightarrow \sigma_1 \tau_1 \tau_2^{-1} \sigma_2^{-1} \in \Gamma \Rightarrow \tau_1 = \tau_2  \Rightarrow  \sigma_1 \sigma_2^{-1} \in SL_2({\mathbb Z}) \Rightarrow \sigma_1 = \sigma_2.
\end{align*}
Here in the second implication we rely on the fact that  $q_1,q_2$ respectively divide the top right, bottom left entries of $\sigma_j$. Therefore, the orbits in $T_{h}^{(q_1)} \, T $ are distinct and has the same cardinality as $T \,  T_{h}^{(q_1)}$, so the two sets of orbits must be equal.

Since $\alpha \in  \mathcal{A}(q_1,q_2,\chi,\xi)$, for $\smqty(a & bq_1 \\ & d) \in  T_{h}^{(q_1)}$ we have  for any $ \sigma \in \operatorname{M}_{2}({\mathbb Z})$ 
\begin{align*}
   \alpha ( \smqty(a & bq_1 \\ & d) \sigma )  = \xi_h \chi(a) \alpha(\sigma)
\end{align*}
and for any $\gamma \in \Gamma$ we have $\alpha(\gamma \sigma) = \overline{\chi}(\gamma)\alpha(\sigma)$. Therefore,  denoting
\begin{align*}
 P_{f}(\tau) :=  \sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) f(\gamma \tau),
\end{align*}
we have
\begin{align*}
     \sum_{\substack{\smqty(a& b \\ c& d)\in \operatorname{M}_{2,h,k}}}  \alpha(\smqty(a & b \\ c & d)) f\bigg(\frac{a}{ \sqrt{|hk|}},\frac{c}{ \sqrt{|hk|}},\frac{d}{ \sqrt{|hk|}}\bigg)&= \sum_{\tau \in \frac{1}{ \sqrt{hk}} \Gamma \backslash \operatorname{M}_{2,h,k}({\mathbb Z}) }\alpha(\tau) P_f (\tau)  \\
     &= \xi_h \sqrt{h}\sum_{\tau \in T} \sum_{\sigma \in \frac{1}{ \sqrt{k}}T_{1,k}} \alpha(\tau \sigma) \mathcal{T}_h P(\tau \sigma),
\end{align*}
where the Hecke operator $\mathcal{T}_h$ (with character $\chi$) is defined in \eqref{eq:gamma2heckedef}. By expanding $\gcd(h,k) =1$ with the M\"obius function we get
\begin{align*}
     &\sum_{\substack{ h,k\\\gcd(h,kq)=1}} \beta_h \gamma_k \sum_{ad-bc = hk}  \alpha (\smqty(a & b \\ c & d)) f\bigg(\frac{a}{ \sqrt{|hk|}},\frac{c}{ \sqrt{|hk|}},\frac{d}{ \sqrt{|hk|}}\bigg) \\
     &= \sum_{\gcd(m,q)=1} \mu(m)   \sum_{\substack{ h,k\\\gcd(h,q)=1 \\ m | h \\ m |k}} \beta_{h} \xi_h \gamma_{k} \sqrt{h}\sum_{\tau \in T} \sum_{\sigma \in k^{-1/2}T_{1,k}} \alpha(\tau \sigma) \mathcal{T}_h P(\tau \sigma).
\end{align*}
Thus, denoting $\beta^{(m)}_h = \beta_h \xi_h \sqrt{h/H} \mathbf{1}_{m|h}, $ and $ \gamma^{(m)}_k= \gamma_k \mathbf{1}_{m|k}$, in the notation of Theorem \ref{thm:Gmainblackbox} we have
\begin{align*}
    \sum_{\substack{ h,k\\\gcd(h,kq)=1}} \beta_h \gamma_k \sum_{ad-bc = hk}  \alpha (\smqty(a & b \\ c & d)) &f\bigg(\frac{a}{ \sqrt{|hk|}},\frac{c}{ \sqrt{|hk|}},\frac{d}{ \sqrt{|hk|}}\bigg)\\
    &=\sum_{\gcd(m,q)=1} \mu(m) H^{1/2} S_{f,\alpha  \star  \gamma^{(m)} ,\beta^{(m)},\chi}(\Gamma,T_0),
\end{align*}
where
\begin{align*}
    T_0 = \bigcup_{k} k^{-1/2} T T_{1,k}
\end{align*}
and
\begin{align*}
    (\alpha \star \gamma^{(m)}) ( \tau_0 ) =  \sum_k \gamma^{(m)}_k \sum_{\substack{\tau_0 = \tau \sigma k^{-1/2}  \\ \tau \in T \\ \sigma \in T_{1,k} } }  \alpha  ( \tau \sigma). 
\end{align*}
We apply Theorem \ref{thm:Gmainblackbox} with
\begin{align*}
    f \in C^7_\delta \bigg( \frac{A}{\sqrt{HK}},\frac{C}{\sqrt{HK}},\frac{D}{\sqrt{HK}}\bigg).
\end{align*}
After substituting in the integral and going back from $\beta^{(m)},\gamma^{(m)}$ to $\beta,\gamma$, the main term in Theorem \ref{thm:Gmainblackbox} matches the one in Theorem \ref{thm:twisteddetwbound}. We get an error of size (after applying Cauchy-Schwarz on $m$)
\begin{align*}
 \ll_\varepsilon  Z^{O(\eta)}  (AD)^{1/2} K^{-1/2}\bigg(\sum_m \mathcal{K}_{\alpha \star \gamma^{(m)} ,\chi}(\Gamma,T_0,L)\bigg)^{1/2}\bigg(\sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N)\bigg)^{1/2},
\end{align*}
It remains to estimate $\mathcal{K}$ and $\mathcal{R}$.

We first consider $\mathcal{K}$. We have 
\begin{align*}
   \frac{1}{K} \sum_m \mathcal{K}_{\alpha \star \gamma^{(m)},\chi}(\Gamma,T,L) = &  \frac{1}{K} \sum_m \sum_{\tau_1, \tau_2 \in T_0} (\alpha \star \gamma^{(m)})(\tau_1)  \overline{(\alpha \star \gamma^{(m)})(\tau_2)}\sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) k_L(\tau_2^{-1} \gamma\tau_1  ) \\
   = &\frac{1}{K} \sum_{k_1,k_2} \sum_{m|\gcd(k_1,k_2)}\gamma_{k_1} \overline{\gamma_{k_2}} \sum_{\sigma_j \in T_{1,k_j}} \sum_{\tau_1, \tau_2 \in T} \alpha (\tau_1 \sigma_1)  \overline{\alpha(\tau_2 \sigma_2 )} \\
  &\times\sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) k_L( k_2^{1/2} \sigma_{2}^{-1}\tau_2^{-1} \gamma\tau_1 \sigma_1  k_1^{-1/2})
\end{align*}
for some function $k_L:G \to [0,1]$ with 
\begin{align*}
k_L(\smqty(a & b \\ c& d)) \leq \mathbf{1}_{|a|+|b| L +|c|/L+|d| \leq 6}.
\end{align*}
By denoting $\sigma = \tau_2^{-1} \gamma \tau_1$ and $g= \sigma_{2}^{-1}\tau_2^{-1} \gamma\tau_1 \sigma_1$ we have by the triangle inequality and a divisor bound to handle $\sum_m$
\begin{align*}
     \frac{1}{K} \sum_m \mathcal{K}_{\alpha \star \gamma^{(m)},\chi}(\Gamma,T,L) \ll_\varepsilon & \frac{Z^\varepsilon}{K} \sum_{k_1,k_2} |\gamma_{k_1} \gamma_{k_2}| \sum_{g \in (k_1/k_2)^{1/2}\operatorname{SL}_2({\mathbb R})}   |k_L( (k_2/k_1)^{1/2} g )| \\
     &\bigg| \sum_{\substack{\sigma_j \in T_{1,k_j} \\ \sigma_2 g \sigma_1^{-1} = \sigma \in \operatorname{SL}_2({\mathbb Z}) }}  \sum_{\substack{\tau_j \in T \\ \tau_2 \sigma  \tau_1^{-1} \in \Gamma }}  \overline{\chi}(\tau_2 \sigma \tau_1^{-1}) \alpha(\tau_1\sigma_1)\overline{\alpha(\tau_2\sigma_2)}\bigg| \\
     \ll_\varepsilon & \frac{Z^\varepsilon}{K} \sum_{k_1,k_2} |\gamma_{k_1} \gamma_{k_2}| \sum_{\substack{g = \smqty(a &b \\mathfrak c& d) \in (k_1/k_2)^{1/2} \operatorname{SL}_2({\mathbb R}) \\ |a| + |b|L + |c|/L +|d| \leq 10}}   \\
     &\bigg| \sum_{\substack{\sigma_j \in T_{1,k_j} \\ \sigma_2 g \sigma_1^{-1} = \sigma \in \operatorname{SL}_2({\mathbb Z}) }}  \sum_{\substack{\tau_j \in T \\ \tau_2 \sigma  \tau_1^{-1} \in \Gamma }}  \overline{\chi}(\tau_2 \sigma \tau_1^{-1}) \alpha(\tau_1\sigma_1)\overline{\alpha(\tau_2\sigma_2)}\bigg| .
\end{align*}
The inner sum is $w(\sigma,\sigma_1,\sigma_2)$. Indeed, in the range of summation $  \tau_1 = \gamma \tau_2 \sigma$ for some  $\gamma \in \Gamma$ since $\Gamma \tau_1 = \Gamma \tau_2 \sigma$. Thus, by using $\alpha \in \mathcal{A}(q_1,q_2,\chi,\xi)$ we get
 \begin{align*}
  \overline{\chi}(\tau_2 \sigma \tau_1^{-1}) \alpha(\tau_1  \sigma_1)  \overline{\alpha(\tau_2  \sigma_2)  } =  \chi(\gamma) \alpha( \gamma \tau_2 \sigma  \sigma_1)  \overline{\alpha(\tau_2  \sigma_2)  }  =   \alpha(  \tau_2 \sigma  \sigma_1)  \overline{\alpha(\tau_2  \sigma_2)  }.
 \end{align*}
To complete the proof of Theorem \ref{thm:twisteddetwbound} we now estimate $\mathcal{R}$ with the help of Corollary \ref{cor:Gmainblackbox}. Applying it gives us that  (ignoring  a factor of $ Z^{O(\eta)}$)
\begin{align*}
\sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N) \ll & \,  \|\beta \xi \|_1|H|^{2\vartheta_q}  \left(1+\bigg(\frac{CD}{ HK q_2 }\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{N}{q}\bigg)^{1-2\theta_q}\right) + \frac{\|\beta \xi \|_1^2}{ N} ,  \\
   \sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N) \ll & \,   \|\beta \xi \|_2^2 \left(1+\bigg(\frac{ CD}{ K q_2}\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{H N}{q}\bigg)^{1-2\theta_q}\right)   +\frac{\|\beta \xi \|_1^2}{ N}.
\end{align*}
Plugging in  $ q_1 C/A \ll N \ll Z^{O(\eta)} q_1 C/A$, we obtain that up to  a factor of $ Z^{O(\eta)}$
\begin{align*}
\sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N) \ll & \,  \|\beta  \xi \|_1^2|H|^{2\vartheta_q}  \left(1+\bigg(\frac{CD}{ HK q_2 }\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{C}{A q_2}\bigg)^{1-2\theta_q}\right)  +\frac{ \|\beta  \xi \|_1^2 A }{q_1 C}, \\
   \sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N)  \ll & \,   \|\beta  \xi  \|_2^2 \left(1+\bigg(\frac{ CD}{ K q_2}\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{H C}{A q_2 }\bigg)^{1-2\theta_q}\right)   +\frac{ \|\beta  \xi \|_1^2 A }{q_1 C},
\end{align*}
as required.
\qed

Recall that
\begin{align*}
    \operatorname{M}_{2,h,k}({\mathbb Z}) = \bigg\{ \mqty(a &b \\ c &d) \in \operatorname{M}_{2,hk}({\mathbb Z}): \, \gcd(a,c,k)=\gcd(b,d,k)=1 \bigg\}.
\end{align*}
Note that the action from left by $\operatorname{SL}_2({\mathbb Z})$ preserves the conditions $\gcd(a,c,k)=\gcd(b,d,k)=1$ so that we may set 
\begin{align*}
  T_{h,k} := \operatorname{SL}_2({\mathbb Z}) \backslash   \operatorname{M}_{2,h,k}({\mathbb Z}).
\end{align*}

Recall that in the statement of Theorem \ref{thm:twisteddetwbound}  we denote $T = \Gamma \backslash \operatorname{SL}_2({\mathbb Z})$, $\Gamma=\Gamma_2(q_1,q_2)$, $q=q_1 q_2$. By definition
\begin{align*}
    \operatorname{M}_{2,h ,k}({\mathbb Z}) =  \operatorname{SL}_2({\mathbb Z})  T_{h,k} = \Gamma \, T \, T_{h,k}.
\end{align*}
Denote further
\begin{align*}
    T_{h}^{(q_1)} = \bigg\{ \mqty(a & bq_1 \\ & d): a,d \in {\mathbb Z}_{>0}, \quad ad = h, \quad b \pmod{d} \bigg\}.
\end{align*}

By $(h,kq) = 1$ we have
\begin{align} \operatorname{M}_{2,h, k}({\mathbb Z}) =   \Gamma \, T \,  T_{h}^{(q_1)} T_{1,k} =    \Gamma \, T_{h}^{(q_1)}\, T \,  T_{1,k}.
\end{align}
Indeed, to show that $\Gamma \, T \,  T_{h}^{(q_1)} = \Gamma \,T_{h}^{(q_1)} \, T  $ we note that for $\sigma_j \in T_{h}^{(q_1)}, \tau_j \in T$
\begin{align*}
    \Gamma \sigma_1 \tau_1 =   \Gamma \sigma_2 \tau_2 \Rightarrow \sigma_1 \tau_1 \tau_2^{-1} \sigma_2^{-1} \in \Gamma \Rightarrow \tau_1 = \tau_2  \Rightarrow  \sigma_1 \sigma_2^{-1} \in SL_2({\mathbb Z}) \Rightarrow \sigma_1 = \sigma_2.
\end{align*}
Here in the second implication we rely on the fact that  $q_1,q_2$ respectively divide the top right, bottom left entries of $\sigma_j$. Therefore, the orbits in $T_{h}^{(q_1)} \, T $ are distinct and has the same cardinality as $T \,  T_{h}^{(q_1)}$, so the two sets of orbits must be equal.

Since $\alpha \in  \mathcal{A}(q_1,q_2,\chi,\xi)$, for $\smqty(a & bq_1 \\ & d) \in  T_{h}^{(q_1)}$ we have  for any $ \sigma \in \operatorname{M}_{2}({\mathbb Z})$ 
\begin{align*}
   \alpha ( \smqty(a & bq_1 \\ & d) \sigma )  = \xi_h \chi(a) \alpha(\sigma)
\end{align*}
and for any $\gamma \in \Gamma$ we have $\alpha(\gamma \sigma) = \overline{\chi}(\gamma)\alpha(\sigma)$. Therefore,  denoting
\begin{align*}
 P_{f}(\tau) :=  \sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) f(\gamma \tau),
\end{align*}
we have
\begin{align*}
     \sum_{\substack{\smqty(a& b \\ c& d)\in \operatorname{M}_{2,h,k}}}  \alpha(\smqty(a & b \\ c & d)) f\bigg(\frac{a}{ \sqrt{|hk|}},\frac{c}{ \sqrt{|hk|}},\frac{d}{ \sqrt{|hk|}}\bigg)&= \sum_{\tau \in \frac{1}{ \sqrt{hk}} \Gamma \backslash \operatorname{M}_{2,h,k}({\mathbb Z}) }\alpha(\tau) P_f (\tau)  \\
     &= \xi_h \sqrt{h}\sum_{\tau \in T} \sum_{\sigma \in \frac{1}{ \sqrt{k}}T_{1,k}} \alpha(\tau \sigma) \mathcal{T}_h P(\tau \sigma),
\end{align*}
where the Hecke operator $\mathcal{T}_h$ (with character $\chi$) is defined in \eqref{eq:gamma2heckedef}.

By expanding $\gcd(h,k) =1$ with the M\"obius function we get
\begin{align*}
     &\sum_{\substack{ h,k\\\gcd(h,kq)=1}} \beta_h \gamma_k \sum_{ad-bc = hk}  \alpha (\smqty(a & b \\ c & d)) f\bigg(\frac{a}{ \sqrt{|hk|}},\frac{c}{ \sqrt{|hk|}},\frac{d}{ \sqrt{|hk|}}\bigg) \\
     &= \sum_{\gcd(m,q)=1} \mu(m)   \sum_{\substack{ h,k\\\gcd(h,q)=1 \\ m | h \\ m |k}} \beta_{h} \xi_h \gamma_{k} \sqrt{h}\sum_{\tau \in T} \sum_{\sigma \in k^{-1/2}T_{1,k}} \alpha(\tau \sigma) \mathcal{T}_h P(\tau \sigma).
\end{align*}
Thus, denoting $\beta^{(m)}_h = \beta_h \xi_h \sqrt{h/H} \mathbf{1}_{m|h}, $ and $ \gamma^{(m)}_k= \gamma_k \mathbf{1}_{m|k}$, in the notation of Theorem \ref{thm:Gmainblackbox} we have
\begin{align*}
    \sum_{\substack{ h,k\\\gcd(h,kq)=1}} \beta_h \gamma_k \sum_{ad-bc = hk}  \alpha (\smqty(a & b \\ c & d)) &f\bigg(\frac{a}{ \sqrt{|hk|}},\frac{c}{ \sqrt{|hk|}},\frac{d}{ \sqrt{|hk|}}\bigg)\\
    &=\sum_{\gcd(m,q)=1} \mu(m) H^{1/2} S_{f,\alpha  \star  \gamma^{(m)} ,\beta^{(m)},\chi}(\Gamma,T_0),
\end{align*}
where
\begin{align*}
    T_0 = \bigcup_{k} k^{-1/2} T T_{1,k}
\end{align*}
and
\begin{align*}
    (\alpha \star \gamma^{(m)}) ( \tau_0 ) =  \sum_k \gamma^{(m)}_k \sum_{\substack{\tau_0 = \tau \sigma k^{-1/2}  \\ \tau \in T \\ \sigma \in T_{1,k} } }  \alpha  ( \tau \sigma). 
\end{align*}

We apply Theorem \ref{thm:Gmainblackbox} with
\begin{align*}
    f \in C^7_\delta \bigg( \frac{A}{\sqrt{HK}},\frac{C}{\sqrt{HK}},\frac{D}{\sqrt{HK}}\bigg).
\end{align*}
After substituting in the integral and going back from $\beta^{(m)},\gamma^{(m)}$ to $\beta,\gamma$, the main term in Theorem \ref{thm:Gmainblackbox} matches the one in Theorem \ref{thm:twisteddetwbound}. We get an error of size (after applying Cauchy-Schwarz on $m$)
\begin{align*}
 \ll_\varepsilon  Z^{O(\eta)}  (AD)^{1/2} K^{-1/2}\bigg(\sum_m \mathcal{K}_{\alpha \star \gamma^{(m)} ,\chi}(\Gamma,T_0,L)\bigg)^{1/2}\bigg(\sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N)\bigg)^{1/2},
\end{align*}
It remains to estimate $\mathcal{K}$ and $\mathcal{R}$.

We first consider $\mathcal{K}$. We have 
\begin{align*}
   \frac{1}{K} \sum_m \mathcal{K}_{\alpha \star \gamma^{(m)},\chi}(\Gamma,T,L) = &  \frac{1}{K} \sum_m \sum_{\tau_1, \tau_2 \in T_0} (\alpha \star \gamma^{(m)})(\tau_1)  \overline{(\alpha \star \gamma^{(m)})(\tau_2)}\sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) k_L(\tau_2^{-1} \gamma\tau_1  ) \\
   = &\frac{1}{K} \sum_{k_1,k_2} \sum_{m|\gcd(k_1,k_2)}\gamma_{k_1} \overline{\gamma_{k_2}} \sum_{\sigma_j \in T_{1,k_j}} \sum_{\tau_1, \tau_2 \in T} \alpha (\tau_1 \sigma_1)  \overline{\alpha(\tau_2 \sigma_2 )} \\
  &\times\sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) k_L( k_2^{1/2} \sigma_{2}^{-1}\tau_2^{-1} \gamma\tau_1 \sigma_1  k_1^{-1/2})
\end{align*}
for some function $k_L:G \to [0,1]$ with 
\begin{align*}
k_L(\smqty(a & b \\ c& d)) \leq \mathbf{1}_{|a|+|b| L +|c|/L+|d| \leq 6}.
\end{align*}
By denoting $\sigma = \tau_2^{-1} \gamma \tau_1$ and $g= \sigma_{2}^{-1}\tau_2^{-1} \gamma\tau_1 \sigma_1$ we have by the triangle inequality and a divisor bound to handle $\sum_m$
\begin{align*}
     \frac{1}{K} \sum_m \mathcal{K}_{\alpha \star \gamma^{(m)},\chi}(\Gamma,T,L) \ll_\varepsilon & \frac{Z^\varepsilon}{K} \sum_{k_1,k_2} |\gamma_{k_1} \gamma_{k_2}| \sum_{g \in (k_1/k_2)^{1/2}\operatorname{SL}_2({\mathbb R})}   |k_L( (k_2/k_1)^{1/2} g )| \\
     &\bigg| \sum_{\substack{\sigma_j \in T_{1,k_j} \\ \sigma_2 g \sigma_1^{-1} = \sigma \in \operatorname{SL}_2({\mathbb Z}) }}  \sum_{\substack{\tau_j \in T \\ \tau_2 \sigma  \tau_1^{-1} \in \Gamma }}  \overline{\chi}(\tau_2 \sigma \tau_1^{-1}) \alpha(\tau_1\sigma_1)\overline{\alpha(\tau_2\sigma_2)}\bigg| \\
     \ll_\varepsilon & \frac{Z^\varepsilon}{K} \sum_{k_1,k_2} |\gamma_{k_1} \gamma_{k_2}| \sum_{\substack{g = \smqty(a &b \\mathfrak c& d) \in (k_1/k_2)^{1/2} \operatorname{SL}_2({\mathbb R}) \\ |a| + |b|L + |c|/L +|d| \leq 10}}   \\
     &\bigg| \sum_{\substack{\sigma_j \in T_{1,k_j} \\ \sigma_2 g \sigma_1^{-1} = \sigma \in \operatorname{SL}_2({\mathbb Z}) }}  \sum_{\substack{\tau_j \in T \\ \tau_2 \sigma  \tau_1^{-1} \in \Gamma }}  \overline{\chi}(\tau_2 \sigma \tau_1^{-1}) \alpha(\tau_1\sigma_1)\overline{\alpha(\tau_2\sigma_2)}\bigg| .
\end{align*}
The inner sum is $w(\sigma,\sigma_1,\sigma_2)$. Indeed, in the range of summation $  \tau_1 = \gamma \tau_2 \sigma$ for some  $\gamma \in \Gamma$ since $\Gamma \tau_1 = \Gamma \tau_2 \sigma$. Thus, by using $\alpha \in \mathcal{A}(q_1,q_2,\chi,\xi)$ we get
 \begin{align*}
  \overline{\chi}(\tau_2 \sigma \tau_1^{-1}) \alpha(\tau_1  \sigma_1)  \overline{\alpha(\tau_2  \sigma_2)  } =  \chi(\gamma) \alpha( \gamma \tau_2 \sigma  \sigma_1)  \overline{\alpha(\tau_2  \sigma_2)  }  =   \alpha(  \tau_2 \sigma  \sigma_1)  \overline{\alpha(\tau_2  \sigma_2)  }.
 \end{align*}

To complete the proof of Theorem \ref{thm:twisteddetwbound} we now estimate $\mathcal{R}$ with the help of Corollary \ref{cor:Gmainblackbox}. Applying it gives us that  (ignoring  a factor of $ Z^{O(\eta)}$)
\begin{align*}
\sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N) \ll & \,  \|\beta \xi \|_1|H|^{2\vartheta_q}  \left(1+\bigg(\frac{CD}{ HK q_2 }\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{N}{q}\bigg)^{1-2\theta_q}\right) + \frac{\|\beta \xi \|_1^2}{ N} ,  \\
   \sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N) \ll & \,   \|\beta \xi \|_2^2 \left(1+\bigg(\frac{ CD}{ K q_2}\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{H N}{q}\bigg)^{1-2\theta_q}\right)   +\frac{\|\beta \xi \|_1^2}{ N}.
\end{align*}
Plugging in  $ q_1 C/A \ll N \ll Z^{O(\eta)} q_1 C/A$, we obtain that up to  a factor of $ Z^{O(\eta)}$
\begin{align*}
\sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N) \ll & \,  \|\beta  \xi \|_1^2|H|^{2\vartheta_q}  \left(1+\bigg(\frac{CD}{ HK q_2 }\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{C}{A q_2}\bigg)^{1-2\theta_q}\right)  +\frac{ \|\beta  \xi \|_1^2 A }{q_1 C}, \\
   \sum_m \mathcal{R}_{\beta^{(m)},\chi}(q_1,q_2,N)  \ll & \,   \|\beta  \xi  \|_2^2 \left(1+\bigg(\frac{ CD}{ K q_2}\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{H C}{A q_2 }\bigg)^{1-2\theta_q}\right)   +\frac{ \|\beta  \xi \|_1^2 A }{q_1 C},
\end{align*}
as required.
\qed

Defining
\begin{align} u(r;p) := \mathbf{1}_{r \equiv 0 \pmod{p}} - p^{-1}, \quad u(r;q_0) := \prod_{p|q_0}u(r;p),
    \end{align}
    we have for square-free $q$
    \begin{align*}
        \mathbf{1}_{n \equiv r \pmod{p}} = \prod_{p|q} \mathbf{1}_{n \equiv r \pmod{p}} =   \prod_{p|q} (u(n-r;p) + p^{-1}) = \sum_{q_0 | q}   \frac{1}{q/q_0}   u(n-r;q_0).
    \end{align*}

Therefore,
\begin{align} \begin{split}
      t(n) &= \sum_{r \pmod{q}} t(r)  \mathbf{1}_{n \equiv r \pmod{p}}  =  \sum_{q_0 | q}  \frac{1}{q/q_0}  \sum_{r \pmod{q}} t(r) u(n-r;q_0) \\
   & = \sum_{q_0 | q} t^{\flat}(n;q_0),
   \\
    t^{\flat}(n;q_0) &:= \sum_{r_0 \pmod{q_0}} t(r_0;q_0) u(n-r_0;q_0), \\
    t(r_0;q_0)  &:= \frac{1}{q/q_0}\sum_{\substack{r \pmod{q} \\ r \equiv r_0 \pmod{q_0}}} t(r).  
\end{split}
\end{align}

Denote
\begin{align*}
    \alpha(\smqty(a & b \\mathfrak c & d);q_0) := t^{\flat}(ad;q_0).
\end{align*}

To this end, we write for $ad-bc=-h$ with $\gcd(h,q)=1$
\begin{align}
  \nonumber   \alpha(\smqty(a & b \\mathfrak c & d);q_0) &=  \alpha(\smqty(a & b \\mathfrak c & d);q_0) \prod_{p|q_0} \bigg( \mathbf{1}_{p|a}+\mathbf{1}_{p|b} +  \mathbf{1}_{\substack{p|c  }}   + \mathbf{1}_{\substack{p |d  }} -\mathbf{1}_{p|\gcd(a,d)} -\mathbf{1}_{p|\gcd(b,c)}+ \mathbf{1}_{ \gcd(abcd,p)=1 }\bigg) \\ &= \sum_{q_0=q_{1} q_{2} q_{3}q_{4}q_5 q_6 q_7}   \alpha(\smqty(a & b \\mathfrak c & d);q_0) \prod_{i=1}^7 v_i(\smqty(a & b \\mathfrak c & d);q_i)=: \sum_{q_0=q_{1} q_{2} q_{3}q_{4}q_5 q_6 q_7} \alpha(\smqty(a & b \\mathfrak c & d);\mathbf{q}),
\end{align}
where
\begin{align*}
    v_1(\smqty(a & b \\mathfrak c & d);q_1) = \mathbf{1}_{q_1|a}, \quad   v_2(\smqty(a & b \\mathfrak c & d);q_2) = \mathbf{1}_{q_2|b},   \quad   v_3(\smqty(a & b \\mathfrak c & d);q_3) = \mathbf{1}_{q_3|c},   \quad   v_4(\smqty(a & b \\mathfrak c & d);q_4) = \mathbf{1}_{q_4|d},  \\
      v_5(\smqty(a & b \\mathfrak c & d);q_1) = \mathbf{1}_{q_5|\gcd(a,d)}, \quad   v_1(\smqty(a & b \\mathfrak c & d);q_1) = \mathbf{1}_{q_6|\gcd(b,c)}, \quad   v_1(\smqty(a & b \\mathfrak c & d);q_1) = \mathbf{1}_{\gcd(abcd,q_7)=1}.
\end{align*}

Denote also
\begin{align*}
   V(\smqty(a & b \\mathfrak c & d);\mathbf{q}) := \prod_{i=1}^7 v_i(\smqty(a & b \\mathfrak c & d);q_i).
\end{align*}

We will apply Theorem \ref{thm:twisteddetwbound} with the group
\begin{align} \Gamma = \Gamma_2(q_1q_2 q_5 q_6 q_7,q_3q_4 q_5 q_6 q_7)=: \Gamma_2(Q_1,Q_2).
\end{align}

Note that
    \begin{align*}
        \mqty(a_0 & b_0 \\mathfrak c_0 & d_0)\mqty(\pm 1 & b \\ & \pm 1) =   \mqty(a_0 & b_0 +b a_0 \\mathfrak c_0 & d_0 + b c_0).
    \end{align*}

Therefore, for $\gcd(r(r+h)s,p)=1$ we have $\gcd(a_0b_0c_0d_0,p)=1$  and the claim follows from the fact that the map
    \begin{align*}
       \{ \smqty(a_0 & b_0 \\ c_0 & d_0) \in \Gamma_2(P_1,P_2) \backslash \operatorname{SL}_2({\mathbb Z}): \gcd(a_0b_0c_0d_0,p)=1 \} &\to \{(r,s) \in {\mathbb Z}/P_1{\mathbb Z} \times {\mathbb Z}/P_2{\mathbb Z} : \, (r(r+h)s,p)=1\} \\
       \smqty(a_0 & b_0 \\ c_0 & d_0) &\mapsto  \bigg(a_0d_0 \frac{-h}{ad-bc},a_0c_0 \frac{-h}{ad-bc}\bigg)
   \end{align*}
  is a bijection. Indeed, clearly this map is surjective (consider $\smqty(a_0 & b_0 \\ c_0 & d_0) = \smqty(1 & b_0 \\ s & r) $ with $r-b_0 s  \equiv 1 \pmod{p}$) and both sets have the same cardinality. Note also that the count is empty if $p=p_j$ for $j \leq 6$ since then $V$ is supported on $p| a_0b_0c_0d_0$ and $(a_0b_0c_0d_0,p)=1$.

For  $p|r(r+h)s$ consider first $p=p_7$. Then
  \begin{align*}
      R_p(r,s,b;\mathbf{p})  \leq  \sum_{\tau= \smqty(a_0 & b_0 \\ c_0 & d_0) \in \Gamma_2(p,p) \backslash \operatorname{SL}_2({\mathbb Z})} \mathbf{1}_{\Pi(\smqty(a_0 & b_0 \\ c_0 & d_0))=(r,s)}\mathbf{1}_{(a_0b_0c_0d_0,p)=1}  \leq 1.
  \end{align*}

For $p=p_1$ we have
  \begin{align*}
      R_p(r,s,b;\mathbf{p})  &\leq  \sum_{\tau= \smqty(a_0 & b_0 \\ c_0 & d_0) \in \Gamma_2(p,1) \backslash \operatorname{SL}_2({\mathbb Z})}  \mathbf{1}_{a_0  \equiv 0 \pmod{p}} \leq 1
  \end{align*}
and for $p=p_6$  we have
  \begin{align*}
      R_p(r,s,b;\mathbf{p})  &\leq  \sum_{\tau= \smqty(a_0 & b_0 \\ c_0 & d_0) \in \Gamma_2(p,p) \backslash \operatorname{SL}_2({\mathbb Z})}  \mathbf{1}_{a_0 \equiv d_0 \equiv 0 \pmod{p}}    \leq 1.
  \end{align*}
The other cases are similar.

Recall the definition of $u$ in \eqref{def:urp} and set
\begin{align*}
    \alpha_r(\smqty(a & b \\ c & d);\mathbf{q}) := u(ad\tfrac{-h}{ad-bc}-r;q_0)  V(\smqty(a & b \\mathfrak c & d);\mathbf{q}).
\end{align*}

Then
\begin{align*}
     &\sum_{\tau \in \Gamma_2(Q_1,Q_2) \backslash \operatorname{SL}_2({\mathbb Z})} \alpha(\tau \smqty(\pm 1 & b \\  & \pm 1) ;\mathbf{q}) \overline{\alpha (\tau;\mathbf{q})}  \\
     &= \sum_{r_1,r_2 \pmod{q_0}} t(r_1;q_0) \overline{t(r_2;q_0)}    \sum_{\tau \in \Gamma_2(Q_1,Q_2)  \backslash \operatorname{SL}_2({\mathbb Z})} \alpha_{r_1}(\tau \smqty(\pm 1& b \\  & \pm 1);\mathbf{q}) \overline{\alpha_{r_2} (\tau;\mathbf{q})} \\
     &=  \sum_{r_1,r_2 \pmod{q}} t(r_1) \overline{t(r_2)}  \frac{1}{(q/q_0)^2}  \sum_{\tau \in \Gamma_2(Q_1,Q_2)  \backslash \operatorname{SL}_2({\mathbb Z})} \alpha_{r_1}(\tau \smqty(\pm 1& b \\  & \pm 1) ;\mathbf{q}) \overline{\alpha_{r_2} (\tau;\mathbf{q})},
\end{align*}
so that it suffices to prove that
\begin{align*}
W(r_1,r_2;\mathbf{q}) := \sum_{\tau \in \Gamma_2(Q_1,Q_2)  \backslash \operatorname{SL}_2({\mathbb Z})} \alpha_{r_1}(\tau \smqty(\pm 1 & b \\  & \pm 1) ;\mathbf{q}) \overline{\alpha_{r_2} (\tau;\mathbf{q})}    
 \\
 \ll_\varepsilon  q^\varepsilon \gcd(b,q_7)  U_h(r_1,r_2;q_0). 
\end{align*}

By the Chinese remainder theorem we have
\begin{align*}
W(r_1,r_2;\mathbf{q})  = \prod_{p|q_0} W(r_1,r_2;\mathbf{p}), 
\end{align*}
where $p_j:=\gcd(p,q_j),P_j:=\gcd(p,Q_j)$, and
\begin{align*}
    W(r_1,r_2;\mathbf{p}) = \sum_{\tau \in \Gamma_2(P_1,P_2)  \backslash \operatorname{SL}_2({\mathbb Z})} \alpha_{r_1}(\tau \smqty(\pm 1 & b \\  & \pm 1) ;\mathbf{p}) \overline{\alpha_{r_2} (\tau;\mathbf{p})} .
\end{align*}

It then suffices to prove that
\begin{align*}
  W(r_1,r_2;\mathbf{p}) \ll \gcd(b,p_7) \bigg( \mathbf{1}_{r_1\equiv 0 \pmod{p}} + \mathbf{1}_{r_2\equiv 0 \pmod{p}} + \mathbf{1}_{r_2\equiv 1 \pmod{p}} + \mathbf{1}_{r_1 \equiv r_2 \pmod{p}} + p^{-1} \bigg).
\end{align*}

To bound $W_2$ we use
   \begin{align*}
       |u(r-r_2;p) u(r+bs-r_1;p)|  \leq \mathbf{1}_{\substack{ r_2\equiv r  \pmod{p} \\ r_1 \equiv r+bs \pmod{p}}}  + p^{-1} (\mathbf{1}_{ r_2 \equiv r  \pmod{p}} + \mathbf{1}_{r_1 \equiv  r+bs \pmod{p}}) + p^{-2}
   \end{align*}
and that by Lemma \ref{le:Rrsbound} $ R_p(r,s,b;\mathbf{p}) \ll 1$ to get
   \begin{align*}
     W_2(r_1,r_2;\mathbf{p}) &\ll   \sum_{\substack{r,s \pmod{p}  \\ p| r(r+h)s}} \bigg(   \mathbf{1}_{\substack{ r_2\equiv r  \pmod{p} \\ r_1 \equiv r+bs \pmod{p}}}  + p^{-1} (\mathbf{1}_{ r_2 \equiv r  \pmod{p}} + \mathbf{1}_{r_1 \equiv  r+bs \pmod{p}}) + p^{-2} \bigg) \\
       &\ll \bigg( \mathbf{1}_{r_1\equiv 0 \pmod{p}} + \mathbf{1}_{r_2\equiv 0 \pmod{p}} + \mathbf{1}_{r_2\equiv -h \pmod{p}} + \mathbf{1}_{r_1 \equiv r_2 \pmod{p}} + p^{-1} \bigg).
   \end{align*}

To bound $W_1$, we have by Lemma \ref{le:Rrsbound} that it is non-zero only for $p=p_7$ and then it is
  \begin{align*}
   W_1(r_1,r_2;p) =    \sum_{\substack{r,s \pmod{p}  \\ \gcd(r(r+h)s,p)=1}} u(r-r_2;p) u(r+bs-r_1;p) =   &\sum_{\substack{r,s \pmod{p}  }} u(r-r_2;p) u(r+bs-r_1;p) \\
       &- \sum_{\substack{r,s \pmod{p}  \\ p| r(r+h)}} u(r-r_2;p) u(r+bs-r_1;p) .
  \end{align*}
  The second term is bounded by the same argument as for $ W_2(r_1,r_2;p)$. For the first term we note that for $\gcd(b,p)=1$ we have by a change of variables, using the definition of $u(r;p)$,
  \begin{align*}
      \sum_{\substack{r,s \pmod{p}  }} u(r-r_2;p) u(r+bs-r_1;p) = \sum_{\substack{r,s \pmod{p} }} u(r;p) u(s;p) = 0,
  \end{align*}
  and for $\gcd(b,p)=p$ we have
  \begin{align*}
       &\sum_{\substack{r,s \pmod{p}  }} u(r-r_2;p) u(r+bs-r_1;p) = \gcd(b,p)     \sum_{\substack{r \pmod{p}  }}  u(r-r_2;p)  u(r-r_1;p) \\
       & \leq \gcd(b,p)     \sum_{\substack{r \pmod{p}  }} (\mathbf{1}_{\substack{ r_2\equiv r  \pmod{p} \\ r_1 \equiv r \pmod{p}}}  + p^{-1} (\mathbf{1}_{ r_2 \equiv r  \pmod{p}} + \mathbf{1}_{r_1 \equiv  r \pmod{p}}) + p^{-2}) \\
      & \ll \gcd(b,p) (  \mathbf{1}_{r_1\equiv r_2 \pmod{p}} + p^{-1} ).
  \end{align*}

Let $\psi:{\mathbb R} \to [0,1]$ be a fixed smooth function, supported on $[1,2]$, and satisfying
\begin{align*}
    \int_{\mathbb R} \psi(1/x) \frac{\mathrm d x}{x} = 1.
\end{align*}

Inserting this thrice and making a change of variables we have
\begin{align*}
  \sum_{ \substack{ad-bc=-h}} G(ad/X) \alpha(\smqty(a & b \\mathfrak c & d);\mathbf{q})&=\int_{{\mathbb R}^3} \sum_{\substack{ad-bc=-h}} G(ad/X)\psi(a/A)\psi(c/C)\psi(d/D)\alpha(\smqty(a & b \\mathfrak c & d);\mathbf{q}) \frac{\mathrm d A \mathrm d C \mathrm d D}{ACD} \\
    &=: \int_{\substack{ A D \leq 2 X \\ C \leq 2(X+|h|)}} S_{\psi}(A,C,D) \frac{\mathrm d A \mathrm d C \mathrm d D}{ACD}.
\end{align*}

Denote also $B := (X+h)/C$.  By symmetry ($ad \leftrightarrow bc$, $a \leftrightarrow d$, $b \leftrightarrow c$) we may assume that
\begin{align*}
    C \ll  X^\eta D \ll X^\eta A \ll  X^{2\eta} B.
\end{align*}
Note that here we have used the assumption $-X/2\leq h \leq X^{1+\eta}$ to infer that $X \ll AD \ll BC \ll X^{1+\eta} .$

Recall $Q_1,Q_2$ from \eqref{eq:Q1Q2def}. If
\begin{align} A > X^{2\eta} Q_1 C \quad \text{or} \quad D > X^{2\eta} Q_2 C,
\end{align}
we obtain the right  main term with sufficiently small error term by Poisson summation. For example, for $ A > X^{2\eta} Q_1 C $ we have
\begin{align*}
    &\sum_{\substack{ad-bc=-h}} G(ad/X)\psi(a/A)\psi(c/C)\psi(d/D) \alpha(\smqty(a & b \\mathfrak c & d);\mathbf{q}) \\
    & = \sum_{\substack{a,c,d \\ad \equiv -h \pmod {c}}} G(ad/X)\psi(a/A)\psi(c/C)\psi(d/D) \alpha(\smqty(a & b \\mathfrak c & d);\mathbf{q})
\end{align*}
where $a$ has a smooth weight on $a \asymp A$. Splitting into residue classes $\pmod{ Q_1}$ and $\pmod{c}$, combining the two residue classes,  applying Poisson summation on $a$ (using $A \geq X^{2\eta}  Q_1 C$),  we get the expected main term and an error term $\ll_J X^{-J}$ for any $J>0$.

It remains to consider the complementary range of \eqref{eq:trivialrangedivisor}, where we can assume that
\begin{align} X^{-\eta}\ll \frac{A}{C} \leq Q_1 X^{2\eta}, \quad X^{-\eta} \ll \frac{D}{C} \leq  Q_2 X^{2\eta} .
\end{align}

We now apply Theorem \ref{thm:twisteddetwbound} to $ S_{\psi}(A,C,D) $ with  
\begin{align*}
\Gamma &= \Gamma_2(Q_1,Q_2)\\
    \beta_{h_0}&=\mathbf{1}_{h_0=-h}, \quad \quad \gamma_k=1_{k=1}, \quad \quad \xi_h=1, \\
   \alpha(\smqty(a& b \\ c & d)) &= \alpha(\smqty(a & b \\mathfrak c & d);\mathbf{q}) =  \alpha\bigg(\mqty(a\frac{-h}{ad-bc} & b\frac{-h}{ad-bc} \\mathfrak c & d);\mathbf{q}\bigg) \in \mathcal{A}(Q_1,Q_2,1,1), 
\end{align*}
where the last expression for $\alpha$ extends its definition to  $\operatorname{M}_2({\mathbb Z})$ with determinant coprime to $q$. As we are only interested in $k=1$, we can adopt the notation in Remark \ref{rem:k=1blackbox} and we have by Lemma \ref{le:balancedlemma}
\begin{align*}
    |w(\smqty( \pm 1 & b \\ & \pm 1))|&\ll_\varepsilon   q^\varepsilon (b,q_7) \mathcal{N}(t).
\end{align*}

We also have by $X^{-\eta} \leq A/C \leq  Q_1 X^{2\eta}, C,D \ll X^{1/2+O(\eta)}$
\begin{align*}
    \mathcal{R}_1&\leq X^{O(\eta)} h^{\vartheta_q}\left(1+\bigg(\frac{X}{h  Q_2 }\bigg)^{\theta} \right)\left(1+ \bigg(\frac{1}{  Q_2}\bigg)^{1/2-\theta}\right)\leq X^{O(\eta)}  h^{\theta}\left(1+\bigg(\frac{X}{h  Q_2 }\bigg)^{\theta} \right), \\
    \mathcal{R}_2&\leq   X^{O(\eta)} \left(1+\bigg(\frac{ X}{ Q_2}\bigg)^{\theta} \right)\left(1+ \bigg(\frac{h }{ Q_2 }\bigg)^{1/2-\theta}\right),
\end{align*}
and
\begin{align*}
   \mathcal{R}_0 = X^{O(\eta)} \frac{ \|\beta\|_1  A^{1/2} }{\|\beta\|_2   Q_1^{1/2} C^{1/2}}\leq 
   X^{O(\eta)} .
\end{align*}

Therefore, by Theorem \ref{thm:twisteddetwbound} the error term is for $h \leq  Q_2$, using $\mathcal{R}_2$,
\begin{align*}
 \ll  X^{1/2+\theta+O(\eta)}  q_0^{1/2-\theta}\mathcal{N}_h(t)^{1/2}  
\end{align*}
and for $h \geq  Q_2$, using $\mathcal{R}_1$,
\begin{align*}
\ll  X^{1/2 +O(\eta)}  q_0^{1/2} \mathcal{N}_h(t)^{1/2}  h^{\theta} + X^{1/2+\theta +O(\eta)}  q_0^{1/2-\theta} \mathcal{N}_h(t)^{1/2}.
\end{align*}

Thus, in either case we get
\begin{align*}
    \ll  X^{1/2+O(\eta)}  q_0^{1/2}\mathcal{N}_h(t)^{1/2}   h^{\theta}  + X^{1/2+\theta+O(\eta)}  q_0^{1/2-\theta}\mathcal{N}_h(t)^{1/2}.
\end{align*}
The main term may be computed by reversing the smooth  dyadic partition and reversing the decomposition \eqref{eq:alphaqxdef}.

We require another decomposition of $t(n)$. To this end, define
    \begin{align*}
        u_0(n;q_0) &:= \mathbf{1}_{n \equiv 0 \pmod{q_0}}, \quad       u_h(n;q_1): = \mathbf{1}_{n \equiv -h \pmod{q_1}}, \\
        v(n;p) &:=  \mathbf{1}_{n \not \equiv 0,-h \pmod{p}}, \quad v(n;q_2) = \prod_{p|q_2}  v(n;p).
    \end{align*}

Then
    \begin{align*}
        t(n) = t(n) \prod_{p|q} \bigg(u_0(n;p) + u_h(n;p) + v(n;p) \bigg) = \sum_{q=q_0 q_1 q_2} t(n)  u_0(n;q_0) u_h(n;q_1) v(n;q_2). 
    \end{align*}

For any prime $p$ and Dirichlet character $\chi$ denote the local conductor
\begin{align*}
    \operatorname{cond}(\chi;p) := \gcd(\operatorname{cond}(\chi),p^\infty) = \max\{p^k | \operatorname{cond}(\chi)\}.
\end{align*}

By Lemma \ref{lem:wsimplification} we have
\begin{align*}
    w(\smqty(\pm 1 & b \\  & \pm 1))= \chi_1 \chi_2 (\pm 1)\sum_{(a_2,b_2) \in \mathbb{P}^{1}_{Q_1} } \sum_{\substack{(c_2,d_2) \in \mathbb{P}^{1}_{Q_2} \\ \gcd(a_2d_2-b_2c_2,Q_0)=1}  } &\psi_1(ba_2\pm b_2)  \overline{\psi_1 }(b_2) |\chi_1  (a_2 )|^2 \\
   &\times\psi_2 (b c_2 \pm d_2) \overline{  \psi_2} (d_2) |\chi_2 (c_2)|^2 
\end{align*}

Recall that a Dirichlet character $\chi$ modulo $q$ is a product of Dirichlet characters modulo $p^k || q$
\begin{align*}
    \chi = \prod_{p |q }\chi^{(p)}.
\end{align*}
For any  $q_1$ with $\gcd(q_1,q/(q,q_1))=1$  we define
\begin{align*}
    \chi^{(q_1)} :=  \prod_{p |q_1 } \chi^{(p)}.
\end{align*}
Denoting
\begin{align*}
  S(q_1,q_2) :=    \sum_{(a_2,b_2) \in \mathbb{P}^{1}_{q_1} } \sum_{\substack{(c_2,d_2) \in \mathbb{P}^{1}_{q_2} \\ \gcd(a_2d_2-b_2c_2,\gcd(q_1,q_2))=1}  }  &\psi_1^{(q_1)} (ba_2\pm b_2)  \overline{\psi_1}^{(q_1)}  (b_2) |\chi_1^{(q_1)}  (a_2 )|^2 \\
   &\times\psi_2^{(q_2)}  (b c_2 \pm d_2) \overline{  \psi_2}^{(q_2)}  (d_2) |\chi_2^{(q_2)}  (c_2)|^2,
\end{align*}
we have by the Chinese remainder theorem
\begin{align*}
    w(\smqty(\pm 1 & b \\  & \pm 1))= \chi_1 \chi_2 (\pm 1)  \prod_{\substack{ \\ p | Q_0}}  S(p,p)  \prod_{\substack{p_j | Q_j \\ p_j \nmid Q_0}}  S(p_1,p_2).
\end{align*}

For $p_j \nmid Q_0$ we have $p_1 \neq p_2$ so that
\begin{align*}
     S(p_1,p_2) = &\bigg(\sum_{(a_2,b_2) \in \mathbb{P}^1_{p_1} }  \psi_1^{(p_1)} (ba_2\pm b_2)  \overline{\psi_1}^{(p_1)}  (b_2) |\chi_1^{(p_1)}  (a_2 )|^2 \bigg)  \\
&\times\bigg(\sum_{\substack{(c_2,d_2) \in \mathbb{P}^1 _{p_2 } }} \psi_2^{(p_2)}  (b c_2 \pm d_2) \overline{  \psi_2}^{(p_2)}  (d_2) |\chi_2^{(p_2)}  (c_2)|^2 \bigg),  
\end{align*}
If  $\gcd (\operatorname{cond} (\psi_j),p_j)|b$  then we use the trivial bound
\begin{align*}
   \sum_{(x,y) \in \mathbb{P}^1_{p_j}}  \psi_j^{(p_j)} (bx\pm y)  \overline{\psi_j}^{(p_j)}  (y) |\chi_j^{(p_j)}  (x )|^2   \ll p_j.
\end{align*}
Otherwise $\gcd(yb,p)=1$, $\psi_j^{(p_j)} $ is non-trivial,  and by writing $r = bx/y$ we get
\begin{align*}
    &\bigg|\sum_{(x,y) \in \mathbb{P}^1_{p_j}}  \psi_j^{(p_j)} (bx\pm y)  \overline{\psi_j}^{(p_j)}  (y) |\chi_j^{(p_j)}  (x )|^2\bigg|= \bigg|\sum_{r \in {\mathbb Z}/p_j {\mathbb Z}} \psi_j^{(p_j)} (r\pm 1)  |\chi_j^{(p_j)}  (r )|^2  \bigg|  \ll 1.
\end{align*}
 Combining the bounds we have for $p_1 \neq p_2$
\begin{align*}
    S(p_1,p_2) \ll  ( 1+ p_1  \mathbf{1}_{\operatorname{cond}(\psi_1;p_1) |b} )( 1+ p_2  \mathbf{1}_{\operatorname{cond}(\psi_2;p_2) |b} )
\end{align*}

For $p| Q_0$ we write
\begin{align*}
    S(p,p) =   S_{0}(p,p) -  S_{1}(p,p)
\end{align*}
where 
\begin{align*}
     S_0(p,p) = &\bigg(\sum_{(a_2,b_2) \in \mathbb{P}^1_{p}}  \psi_1^{(p)} (ba_2\pm b_2)  \overline{\psi_1}^{(p)}  (b_2) |\chi_1^{(p)}  (a_2 )|^2 \bigg)  \\
&\times\bigg(\sum_{\substack{(c_2,d_2) \in \mathbb{P}^1 _{p } }} \psi_2^{(p)}  (b c_2 \pm d_2) \overline{  \psi_2}^{(p)}  (d_2) |\chi_2^{(p)}  (c_2)|^2 \bigg),  
\end{align*}
and
\begin{align*}
     S_1(p,p) = \sum_{(a_2,b_2) \in \mathbb{P}^1_{p}} & \psi_1^{(p)} (ba_2\pm b_2)  \overline{\psi_1}^{(p)}  (b_2) |\chi_1^{(p)}  (a_2 )|^2   \\
&\sum_{\substack{(c_2,d_2) \in \mathbb{P}^1 _{p}  \\ p| a_2 d_2-b_2 c_2} } \psi_2^{(p)}  (b c_2 \pm d_2) \overline{  \psi_2}^{(p)}  (d_2) |\chi_2^{(p)}  (c_2)|^2,  
\end{align*}
By the previous argument we have
\begin{align*}
    S_0(p,p) \ll   ( 1+ p  \mathbf{1}_{\operatorname{cond}(\psi_1;p) |b} )( 1+ p  \mathbf{1}_{\operatorname{cond}(\psi_2;p) |b} ).
\end{align*}
For $S_1(p,p)$ we note that $p|a_2 d_2-b_2c_2$ means precisely that $(a_2,b_2) \sim (c_2,d_2)$ as points in $\mathbb{P}^1_p$ so that trivially
\begin{align*}
     S_1(p,p)  \ll p
\end{align*}
Therefore,
\begin{align*}
      S(p,p) \ll ( 1+ p  \mathbf{1}_{\operatorname{cond}(\psi_1;p) |b} )( 1+ p  \mathbf{1}_{\operatorname{cond}(\psi_2;p) |b} ) + p.
\end{align*}

Defining a multiplicative function $F(\cdot,b)$ by 
\begin{align*}
    F(p^k; b) := \begin{cases}
    1+p\mathbf{1}_{\operatorname{cond}(\psi_j;p) |b}  \quad & p | Q_j, p \nmid Q_0, \\
    ( 1+ p  \mathbf{1}_{\operatorname{cond}(\psi_1;p) |b} )( 1+ p  \mathbf{1}_{\operatorname{cond}(\psi_2;p) |b} ) + p   \quad &p | Q_0 \end{cases},
\end{align*}
and $F(p^k,b)=1$ for $p \nmid Q_1Q_2$, we have
\begin{align*}
  | w(\smqty(\pm 1 & b \\  & \pm 1))| \ll_\varepsilon (Q_1Q_2)^{\varepsilon}  F(Q_1 Q_2; b).
\end{align*}
Then  $F(Q_1 Q_2; b) = F(Q_1 Q_2, \gcd(b,(Q_1Q_2)))$ and for $d_1 d_2|Q_1Q_2$ with $\gcd(d_1,d_2)=1$  we have \begin{align*}
    F(Q_1 Q_2; d_1 d_2) = F(Q_1 Q_2; d_1 ) F(Q_1 Q_2; d_2)
\end{align*}
Therefore, we get
\begin{align*}
    \sum_{0<b \leq B}  | w(\smqty(\pm 1 & b \\  & \pm 1))| &\ll_\varepsilon (Q_1Q_2)^{\varepsilon} \sum_{0<b \leq B}   F(Q_1 Q_2; b)  =(Q_1Q_2)^{\varepsilon} \sum_{d | Q_1 Q_2} F(Q_1 Q_2; d)  \sum_{\substack{0<b \leq B \\ \gcd(b,Q_1Q_2)=d}} 1 \\
    &\ll_\varepsilon (Q_1Q_2)^{\varepsilon}  B \sum_{d | Q_1 Q_2} \frac{F(Q_1 Q_2; d)}{d} \leq (Q_1Q_2)^{\varepsilon} B \prod_{p| Q_1 Q_2} \bigg( \sum_{0 \leq k \leq 2 } \frac{F(Q_1 Q_2; p^k)}{p^k} \bigg)    \\
   & \ll_\varepsilon B (Q_1Q_2)^{1+\varepsilon} \prod_{\substack{p| Q_j \\ p \nmid Q_0}} \frac{1}{\operatorname{cond}(\psi_j;p)}  \prod_{\substack{ p \mid Q_0}} \frac{1}{\max_j \{\operatorname{cond}(\psi_j;p)\}},
\end{align*}
since for $p|Q_j,p\nmid Q_0$ we have $\frac{F(Q_1 Q_2; p^k)}{p^k}  \leq 2\frac{p}{\operatorname{cond}(\psi_j;p)}$, and for $p| Q_0$ we have for both $j\in\{1,2\}$ that $\frac{F(Q_1 Q_2; p^k)}{p^k}  \leq 5\frac{p^2}{\operatorname{cond}(\psi_j;p)}$.

Let $\eta>0$ be small and let $U:{\mathbb R} \to [0,1]$ be a smooth function such that
\begin{align*}
    U(\xi) = 1, \quad |\xi| \leq T^{-1+\eta} \quad \text{and} \quad  U(\xi) = 0, \quad |\xi| \leq 2T^{-1+\eta}.
\end{align*}
Assume that $U^{(j)}(\xi) \ll_j |\xi|^{-j}$ for $\xi > 0$.
Let $V:(0,\infty) \to [0,1]$ be a fixed smooth function with
\begin{align*}
    V(\xi) + V(\xi^{-1}) = 1, \quad \xi >0, \quad \text{and} \quad V(\xi) = 0, \quad \xi \geq 2.
\end{align*}
We denote
 \begin{align*}
          d_{\chi_1,\chi_2}(n)=\sum_{ad=n}\chi_1(a)\chi_2(d).
      \end{align*}

We now bring $ S_{\chi_1,\chi_2} (t,U,V) $ into the right shape for the application of Theorem \ref{thm:twisteddetwbound}. We start this process by sorting after the determinant. Denoting $h= n_2-n_1$, $n_2=ad$ and $n_1=bc$ we get
\begin{align*}
     S_{\chi_1,\chi_2}(t,U,V)=\sum_{h \neq 0} \sum_{\smqty(a& b \\ c & d)\in \operatorname{M}_{2,h}({\mathbb Z})} \chi_1(a)\overline{\chi_1}(b)\overline{\chi_2}(c) \chi_2(d) g_{t,h}(a,c,d)
\end{align*}
where
\begin{align*}
    g_{t,h}(a,c,d)= e\bigg( -\frac{t}{2 \pi } \log( 1-\frac{h}{ad})\bigg) U\bigg(\frac{h}{ad}\bigg) V\bigg( \frac{ad}{t \sqrt{q_1 q_2}}\bigg) \frac{1}{h\sqrt{ad/h}\sqrt{ad/h-1}}.
\end{align*}
Here by symmetry we restrict to $h \geq 1$.  By Mellin inversion we have
\begin{align*}
    V\bigg( \frac{ad}{t \sqrt{q_1 q_2}}\bigg) = \frac{1}{2\pi } \int_{(0)} \bigg( \frac{ad}{t \sqrt{q_1 q_2}}\bigg)^{-s} \widetilde{V}(s) \mathrm d s,
\end{align*}
where integration by parts gives the bounds
\begin{align*}
   \widetilde{V}(s) = \int_0^\infty V(\xi) \xi^{s-1} \mathrm d \xi  \ll_{\sigma,J} (1+|s|)^{-J}.  
\end{align*}
Thus,
\begin{align*}
     S_{\chi_1,\chi_2}(t,U,V) =  \frac{1}{2\pi } \int_{(0)}  (t\sqrt{q_1q_2})^{s}   \widetilde{V}(s)  S_{\chi_1,\chi_2,s}(t,U)\mathrm d s
\end{align*}
with
\begin{align*}
    S_{\chi_1,\chi_2,s}(t,U) =  \sum_{h \geq 1} h^{s-1} \sum_{\smqty(a& b \\ c & d)\in \operatorname{M}_{2,h}({\mathbb Z})} \chi_1(a)\overline{\chi_1}(b)\overline{\chi_2}(c) \chi_2(d) f_{t,s}\bigg(\frac{a}{\sqrt{h}},\frac{c}{\sqrt{h}},\frac{d}{\sqrt{h}}\bigg),
\end{align*}
where
\begin{align*}
    f_{t,s}(a,c,d)  = e\bigg( -\frac{t}{2 \pi } \log( 1-\frac{1}{ad})\bigg) U\bigg(\frac{1}{ad}\bigg)  (ad)^{-s} \frac{1}{\sqrt{ad}\sqrt{ad-1}}.
\end{align*}

The contribution from $|s| \geq T^\eta$ is negligible so we consider $|s| \leq T^\eta$. Inserting a dyadic decomposition for $h$ and a smooth dyadic decomposition for $a/\sqrt{h},c/\sqrt{h},d/\sqrt{h}$ we obtain sums of the form
\begin{align*}
     S_{\chi_1,\chi_2,s,t}(A,C,D,H) := \frac{1}{AD}  \sum_{h \sim H}  H h^{s-1} \sum_{\smqty(a& b \\ c & d)\in \operatorname{M}_{2,h}({\mathbb Z})} \chi_1(a)\overline{\chi_1}(b)\overline{\chi_2}(c) \chi_2(d) f\bigg(\frac{a}{\sqrt{h}},\frac{c}{\sqrt{h}},\frac{d}{\sqrt{h}}\bigg).
\end{align*}
Here we need to consider the ranges of variables
\begin{align} H \ll T^\eta AD/T, \quad T^{1-\eta} \ll AD,BC \ll T \sqrt{q_1q_2},
\end{align} 
and the involved weight
\begin{align*}
    f(a,c,d) :=   \frac{AD}{H} f_{t,s}(a,c,d) \psi\bigg(a \frac{\sqrt{H}}{A}\bigg) \psi\bigg(c\frac{\sqrt{H}}{C}\bigg) \psi\bigg(d\frac{\sqrt{H}}{D}\bigg)\in C^{J}_{\delta}\bigg( \frac{A}{\sqrt{H}},\frac{C}{\sqrt{H}},\frac{D}{\sqrt{H}}\bigg)
\end{align*}
with $\delta^{-1} \ll T^{O_J(\eta)}$ fulfills the assumption of Theorem \ref{thm:twisteddetwbound}.

By splitting into congruence classes and using Poisson summation on the longest variable, we get a main term with arbitrary power saving in the error term as long as
\begin{align}
    \max\{A/q_1,D/q_2\} > Z^\eta \min \{B,C\} \quad \text{or} \quad \max\{B/q_1,C/q_2\} > Z^\eta  \min\{A,D\}.
\end{align}
In the complementary range we may assume that
\begin{align} q_2^{-1} Z^{-\eta} <  C/D \leq q_2 Z^\eta, \quad     q_1^{-1} Z^{-\eta} <  C/A \leq q_2 Z^\eta.
\end{align}

For a fixed $k$ denote $r_j := q_j/(k,q_j)$. Since $q_j$ are square-free, we have $\gcd(r_1r_2,k)=1$ and we can fix a choice of representatives
\begin{align*}
    \operatorname{SL}_2({\mathbb Z}) \backslash \operatorname{M}_{2,1,k}({\mathbb Z}) =T_{1,k} =\bigg\{ \mqty(1 & f r_1r_2 \\ & k), \quad 1\leq f < k, \quad \gcd(f,k)=1\bigg\}.
\end{align*}
Then for any $\tau= \smqty(a_0 & b_0 \\ c_0 & d_0) \in \operatorname{M}_{2,h}({\mathbb Z})$ and $\sigma=\smqty(1 & f r_1r_2 \\ & k) \in T_{1,k}$ we have
\begin{align} \tau \sigma =   \mqty(a_0 & b_0 \\ c_0 & d_0) \mqty(1 & f r_1r_2 \\ & k) =  \mqty(a_0 & a_0f r_1r_2+ b_0k \\ c_0 & c_0 f r_1r_2 + d_0k). 
\end{align}
Denoting the unique decomposition of characters
\begin{align*}
    \chi_j = \chi^{(k)}_{j} \chi_{j}^{(r_j)}, \quad \chi^{(k)}_{j} \in \widehat{({\mathbb Z}/\gcd(k,q_j){\mathbb Z})^\times}, \quad\chi_{j}^{(r_j)} \in \widehat{({\mathbb Z}/r_j{\mathbb Z})^\times},
\end{align*}
we have for $g = \smqty(a & b \\ c& d) = \tau \sigma$ as above
\begin{align*}
    \chi_1(a)\overline{\chi_1}(b)\overline{\chi_2}(c) \chi_2(d)  = & \chi^{(k)}_{1} (f_j r_1 r_2) \chi^{(k)}_{2} (f_j r_1 r_2)   \chi_{1}^{(r_j)}(k a_0) \overline{\chi_{1}^{(r_1)}}(b_0) \chi_{2}^{(r_2)}(k c_0) \overline{\chi_{1}^{(r_2)}}(d_0) \mathbf{1}_{(a,b,k)=1} \mathbf{1}_{(c,d,k)=1} \\
    =: & \, \alpha_0(g) \mathbf{1}_{\gcd(a,b,k)=1} \mathbf{1}_{\gcd(c,d,k)=1}
\end{align*}
Expanding the conditions $\gcd(a,b,k)=1$ and $\gcd(c,d,k)=1$ via the M\"obius function we have (since by $\gcd(h,k)=1$ we have $k_1k_2 |k$)
\begin{align*}
 S_{\chi_1,\chi_2,s,t,k}(A,C,D,H) &= \sum_{k_1k_2 | k} \mu(k_1) \mu(k_2)  S_{\chi_1,\chi_2,s,t,k,k_j}(A,C,D,H), \\
 S_{\chi_1,\chi_2,s,t,k,k_j}(A,C,D,H) &:=  \sum_{\substack{h \sim H/k \\ \gcd(h,q_1q_2)=1}} \frac{H}{k} h^{s-1}\sum_{\substack{g=\smqty(a& b \\ c & d)\in \operatorname{M}_{2,h,k}({\mathbb Z}) \\ k_1|\gcd(a,b) \\ k_2 | \gcd(c,d)}} \alpha_0(g) f\bigg(\frac{a}{\sqrt{hk}},\frac{c}{\sqrt{hk}},\frac{d}{\sqrt{hk}}\bigg).
\end{align*}
Here for $\smqty(a&b \\ c& d)=\tau \sigma$ as in \eqref{eq:tausigmadef} we have
\begin{align} \nonumber
\alpha(\smqty(a & b \\ c & d)) &:=  \alpha_0(\smqty(a & b \\ c & d)) \mathbf{1}_{\substack{k_1|\gcd(a,b )\\ k_2 |\gcd(c,d) }} = \mathbf{1}_{\substack{k_1 | a_0 \\ k_2 | c_0}} \alpha_0(\tau \sigma)   \\ \nonumber
&= \chi^{(k)}_{1} (f_j r_1 r_2) \chi_{1}^{(r_j)}(k )\chi^{(k)}_{2} (f_j r_1 r_2) \chi_{2}^{(r_2)}(k)   \chi_{1}^{(r_j)}( a_0) \overline{\chi_{1}^{(r_1)}}(b_0) \chi_{2}^{(r_2)}( c_0) \overline{\chi_{1}^{(r_2)}}(d_0) \mathbf{1}_{\substack{k_1 | a_0 \\ k_2 | c_0}}  \\ &=: \alpha_k (\sigma) \alpha_{r_j,k_j}(\tau).
\end{align}
This is for $\det \smqty(a & b \\ c & d)=hk$ invariant under the action $\Gamma_2(r_1 k_1 ,r_2k_2)$, that is, for $\gamma \in \Gamma_2(r_1k_1,r_2k_2) $  and for any $g \in \operatorname{M}_{2,h,k}({\mathbb Z})$ we have $\alpha_0(\gamma g) = \alpha_0(g)$. This is clear since the action by $\gamma$ does not change the Hecke representative $\sigma \in T_{1,k}$ and the weight $\alpha_{r_j,k_j}(\tau)$ is invariant. It then follows that $\alpha \in \mathcal{A}(r_1k_1,r_2k_2,1,1)$. Thus, we are ready to apply Theorem \ref{thm:twisteddetwbound} for each fixed $k$ and with $\alpha$ as given above,
\begin{align*}
    \beta_h = \mathbf{1}_{h \sim H/k}\mathbf{1}_{\gcd(h,q)=1}\frac{H}{k} h^{s-1}\quad \text{and} \quad \gamma_{k_0} = \mathbf{1}_{k_0 = k}.
\end{align*}

We claim that \eqref{eq:Kassumptiongeneral} holds in the form
\begin{align} \frac{1}{k}\sum_{\substack{g = \smqty(a &b \\ c &d ) \in \operatorname{SL}_2({\mathbb R}) \\ |a| + |b|C/D + |c|D/C + |d| \leq 10 }} \bigg| \sum_{\substack{\sigma_1,\sigma_2 \in T_{1,k} \\ \sigma_2 g \sigma_1^{-1} =\sigma \in \operatorname{SL}_2({\mathbb Z}) }} w(\sigma,\sigma_1,\sigma_2)\bigg| \ll_\varepsilon   Z^{\varepsilon} k \bigg(r_1r_2 + (r_1,r_2) ( C/D + D/C)\bigg).
\end{align}

Assuming this and applying Theorem \ref{thm:twisteddetwbound} we get
\begin{align*}
    S_{\chi_1,\chi_2,s,t,k}(A,C,D,H) = \mathrm{MT}_{\chi_1,\chi_2,s,t,k} + O(T^{O(\eta)} (AD)^{1/2} \|\beta\|_2 \mathcal{K}_+^{1/2} (\mathcal{R}_0 + \mathcal{R}_2 )  )
\end{align*}
with
\begin{align*}
     \|\beta\|_2 &\ll \frac{H^{1/2}}{k^{1/2}}, \\
     \mathcal{K}_+^{1/2} &\ll k^{1/2} (r_1r_2)^{1/2} + k^{1/2} (r_1,r_2)^{1/2} (C/D+D/C)^{1/2}, \\
     \mathcal{R}_0 &\ll \frac{H^{1/2}}{k^{1/2}}  \frac{A^{1/2}}{r_1^{1/2} C^{1/2}}, \\
     \mathcal{R}_2&\ll \bigg( 1+ \bigg(\frac{CD}{k r_2}\bigg)^{\theta}\bigg) \bigg( 1+ \bigg(\frac{HC}{k A r_2}\bigg)^{1/2-\theta}\bigg).
\end{align*}
By \eqref{eq:ratioassumption}, writing $CD= AD C/A \leq AD q_2 Z^\eta$ and $H \leq T^\eta AD/T$ we get
\begin{align*}
     \|\beta\|_2 &\ll \frac{H^{1/2}}{k^{1/2}} \ll k^{-1/2} (AD)^{1/2} T^{-1/2} , \\
     \mathcal{K}_+^{1/2} &\ll k^{1/2} (r_1r_2)^{1/2} + k^{1/2} (r_1,r_2)^{1/2} q_2^{1/2}, \\
     \mathcal{R}_0 &\ll H^{1/2}k^{-1/2}  (q_1/r_1)^{1/2} \ll (AD)^{1/2}   T^{-1/2} k^{-1/2}  (q_1/r_1)^{1/2} , \\
     \mathcal{R}_2&\ll  \bigg(\frac{AD q_2}{k r_2}\bigg)^{\theta}  \bigg(\frac{H q_2}{k r_2}\bigg)^{1/2-\theta} = (AD)^{1/2} k^{-1/2} T^{-1/2+\theta}  (q_2/r_2)^{1/2}.
\end{align*}
Thus, by \eqref{eq:HADrange} we get a total contribution to the error term (after summing over $k |q^{\infty}$ and integrating over $t \asymp T$, recalling the normalization by $\frac{1}{AD}$ in \eqref{eq:ADnormalization})
\begin{align*}
   & \ll T^{O(\eta)} \frac{T}{AD} (AD)^{1/2}  \|\beta\|_2 E^{1/2} (\mathcal{R}_0 + \mathcal{R}_2 )  \\
   & \ll   T^{O(\eta)}  T^\theta (AD)^{1/2} ((q_1/r_1)^{1/2} + (q_2/r_2)^{1/2})((r_1r_2)^{1/2} + (r_1,r_2)^{1/2} q_2^{1/2}) \\
   & \ll  T^{O(\eta)}   T^\theta  (AD)^{1/2}  ( \sqrt{q_1q_2} + q_2   ) \\
     & \ll  T^{O(\eta)}   T^{1/2+\theta} (q_1q_2)^{3/4},
\end{align*}
since by symmetry we may assume that $q_2 \leq q_1$. The main term can be calculated by reversing the previous steps. This proves Theorem \ref{cor:Lfunction}  under the assumption of \eqref{claim:LfunctionKbound}.

Denoting $L:=C/D$, we need to bound
\begin{align*}
\mathcal{K} := \sum_{\substack{g = \smqty(a &b \\ c &d ) \in  \operatorname{SL}_2({\mathbb R}) \\ |a| + |b|L + |c|/L + |d| \leq 10 }} \bigg| \sum_{\substack{\sigma_1,\sigma_2 \in T_{1,k} \\ \sigma_2 g \sigma_1^{-1} =\sigma \in \operatorname{SL}_2({\mathbb Z}) }} w(\sigma,\sigma_1,\sigma_2)\bigg|.
\end{align*}
By \eqref{eq:alphakrk}
\begin{align*}  w(\sigma,\sigma_1,\sigma_2)&=\sum_{\substack{\tau\in \Gamma_2(r_1k_1,r_2k_2) \backslash \operatorname{SL}_2({\mathbb Z})}  } \alpha_0(\tau \sigma \sigma_1)\overline{\alpha_0(\tau \sigma_2)} \\
&= \alpha_k(\sigma_1) \overline{\alpha_k(\sigma_2)} \sum_{\substack{\tau\in \Gamma_2(r_1k_1,r_2k_2) \backslash \operatorname{SL}_2({\mathbb Z})}  } \alpha_{r_j,k_j}(\tau \sigma)\overline{\alpha_{r_j,k_j}(\tau)}   \\
& = \mathbf{1}_{\substack{\sigma = \smqty(a & b \\ c & d) \\ k_2 | c ,\, k_1 | d } }  \,\alpha_k(\sigma_1) \overline{\alpha_k(\sigma_2)} \sum_{\substack{\tau\in \Gamma_2(r_1,r_2) \backslash \operatorname{SL}_2({\mathbb Z})}  }  \alpha^{(r_1,r_2)}(\tau \sigma)\overline{\alpha^{(r_1,r_2)}(\tau)},
\end{align*}
where we have denoted
\begin{align*}
  \alpha^{(r_1,r_2)}(\smqty(a_0 & b_0 \\ c_0 & d_0)) :=  \chi_{1}^{(r_j)}( a_0) \overline{\chi_{1}^{(r_1)}}(b_0) \chi_{2}^{(r_2)}( c_0) \overline{\chi_{1}^{(r_2)}}(d_0).
\end{align*}
We thus have 
\begin{align*}
|w(\sigma,\sigma_1,\sigma_2)| \leq \bigg|\sum_{\substack{\tau\in  \Gamma_2(r_1,r_2) \backslash \operatorname{SL}_2({\mathbb Z})}  } \alpha^{(r_1,r_2)}(\tau \sigma) \overline{\alpha^{(r_1,r_2)}(\tau) } \bigg| =: w_0(\sigma), 
\end{align*}
which is as in Lemma \ref{le:charactersumbound}. Recall that $q_j$ are square-free so that $(r_j,k)=1$, and we use representatives for $T_{1,k}$ of the form
\begin{align*}
    \sigma_j = \mqty(1 & f_j r_1 r_2 \\ & k), \quad 1 \leq f_j < k, \quad \gcd(f_j,k)=1.
\end{align*}
 By a change of variables  we get
\begin{align*}
      \mathcal{K} 
 &=    \sum_{\sigma \in \operatorname{SL}_2({\mathbb Z})} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10}} 1 
    =  \mathcal{K}_{1} + \mathcal{K}_{2} + \mathcal{K}_3, \\
      \mathcal{K}_1 &:=  \sum_{\substack{\sigma= \smqty(a & b \\ c& d) \in \operatorname{SL}_2({\mathbb Z}) \\mathfrak c=0}} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10}} 1   , \\
       \mathcal{K}_2  &:=    \sum_{\substack{\sigma= \smqty(a & b \\ c& d) \in \operatorname{SL}_2({\mathbb Z}) \\ c \neq 0}} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\  b_0= 0}} 1,  \\
     \mathcal{K}_3 &:=  \sum_{\substack{\sigma= \smqty(a & b \\ c& d) \in \operatorname{SL}_2({\mathbb Z}) \\ c \neq 0}} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\  b_0 \neq 0}} 1.
\end{align*} 
Here for $\sigma = \smqty(a &b \\ c& d)$
\begin{align*}
   \mqty(a_0 & b_0 \\mathfrak c_0 & d_0 )=  \sigma_2^{-1} \sigma \sigma_1  = \mqty(a-cf_2 r_1 r_2/k & f_1 r_1 r_2 a-f_2 r_1 r_2 d+kb-cf_1f_2 (r_1r_2)^2/k\\ c/k & d+cf_1 r_1 r_2/k).
\end{align*}

We have by Lemma \ref{le:charactersumbound} 
