   \ll &  k  \sum_{\smqty(\pm 1 & b \\ & \pm 1) \in \operatorname{SL}_2({\mathbb Z})}  \sum_{\substack{ |f| \leq k \\ |f r_1 r_2 \pm k b| \leq 10 /L}} w_0(\smqty(\pm 1 & b \\ & \pm 1) ) \\
   \ll & k \sum_{|b_0| \leq 10 /L} w_0(\smqty(\pm 1 & b_0 \\ & \pm 1) ) \ll_\varepsilon Z^{\varepsilon} k \bigg(r_1 r_2 +  \frac{\gcd(r_1,r_2)}{L }\bigg)
