\begin{align*}
      \mathcal{K}_{3} \ll & (r_1r_2)^{1+\varepsilon}   \sum_{\substack{\smqty(a & b \\ c & d) \in \operatorname{SL}_2({\mathbb Z}) \\ c \neq 0  }}\sum_{\substack{\sigma_1,\sigma_2 \in T_{1,k} \\   \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\ b_0 \neq 0  }} 1.
     \\  \ll & \,  (r_1r_2)^{1+\varepsilon}   \sum_{\substack{\smqty(a_1 & b_1 \\ c_1 & d_1) \in \operatorname{M}_{2,k}({\mathbb Z}) \\ c \neq 0 \\ }}\sum_{\substack{\sigma_2 \in T_{1,k} \\   \sigma_2^{-1} \smqty(a_1 & b_1 \\ c_1 & d_1) = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\ b_0 \neq 0}} 1. 
\end{align*}
Here
\begin{align*}
   \mqty(a_0 & b_0 \\mathfrak c_0 & d_0 )  =  \frac{1}{k} \mqty(k & -f_2 r_1r_2 \\ & 1) \mqty(a_1 & b_1 \\ c_1 & d_1)  = \frac{1}{k} \mqty(k a_1-f_2 r_1r_2  c_1 & k b_1-f_2 r_1r_2  d_1 \\ c_1 & d_1) = \frac{1}{k} \mqty(a_2 & b_2 \\ c_2 &  d_2).
\end{align*}
Thus, summing over $f_2$ and combining the variables (using $(k,r_1r_2)=1$) we get
\begin{align*}
  \mathcal{K}_{3} & \ll (r_1r_2)^{1+\varepsilon} \sum_{\substack{a_2 d_2 -b_2 c_2 = k^2 \\ |a_2|/k + |b_2|L/k + |c_2|/(kL) + |d_2| /k \leq 10  \\ b_2 c_2 \neq  0}} 1 \\
   & \ll  (r_1r_2)^{1+\varepsilon}  \sum_{\substack{a_2,d_2 \ll  k \\ a_2d_2 \neq k^2}} \tau(a_2 d_1 -k^2) \\
    & \ll  k^2(r_1r_2)^{1+\varepsilon} .
\end{align*}

Denoting $L:=C/D$, we need to bound
\begin{align*}
\mathcal{K} := \sum_{\substack{g = \smqty(a &b \\ c &d ) \in  \operatorname{SL}_2({\mathbb R}) \\ |a| + |b|L + |c|/L + |d| \leq 10 }} \bigg| \sum_{\substack{\sigma_1,\sigma_2 \in T_{1,k} \\ \sigma_2 g \sigma_1^{-1} =\sigma \in \operatorname{SL}_2({\mathbb Z}) }} w(\sigma,\sigma_1,\sigma_2)\bigg|.
\end{align*}

By \eqref{eq:alphakrk}
\begin{align*}  w(\sigma,\sigma_1,\sigma_2)&=\sum_{\substack{\tau\in \Gamma_2(r_1k_1,r_2k_2) \backslash \operatorname{SL}_2({\mathbb Z})}  } \alpha_0(\tau \sigma \sigma_1)\overline{\alpha_0(\tau \sigma_2)} \\
&= \alpha_k(\sigma_1) \overline{\alpha_k(\sigma_2)} \sum_{\substack{\tau\in \Gamma_2(r_1k_1,r_2k_2) \backslash \operatorname{SL}_2({\mathbb Z})}  } \alpha_{r_j,k_j}(\tau \sigma)\overline{\alpha_{r_j,k_j}(\tau)}   \\
& = \mathbf{1}_{\substack{\sigma = \smqty(a & b \\ c & d) \\ k_2 | c ,\, k_1 | d } }  \,\alpha_k(\sigma_1) \overline{\alpha_k(\sigma_2)} \sum_{\substack{\tau\in \Gamma_2(r_1,r_2) \backslash \operatorname{SL}_2({\mathbb Z})}  }  \alpha^{(r_1,r_2)}(\tau \sigma)\overline{\alpha^{(r_1,r_2)}(\tau)},
\end{align*}
where we have denoted
\begin{align*}
  \alpha^{(r_1,r_2)}(\smqty(a_0 & b_0 \\ c_0 & d_0)) :=  \chi_{1}^{(r_j)}( a_0) \overline{\chi_{1}^{(r_1)}}(b_0) \chi_{2}^{(r_2)}( c_0) \overline{\chi_{1}^{(r_2)}}(d_0).
\end{align*}
We thus have 
\begin{align*}
|w(\sigma,\sigma_1,\sigma_2)| \leq \bigg|\sum_{\substack{\tau\in  \Gamma_2(r_1,r_2) \backslash \operatorname{SL}_2({\mathbb Z})}  } \alpha^{(r_1,r_2)}(\tau \sigma) \overline{\alpha^{(r_1,r_2)}(\tau) } \bigg| =: w_0(\sigma), 
\end{align*}
which is as in Lemma \ref{le:charactersumbound}.

Recall that $q_j$ are square-free so that $(r_j,k)=1$, and we use representatives for $T_{1,k}$ of the form
\begin{align*}
    \sigma_j = \mqty(1 & f_j r_1 r_2 \\ & k), \quad 1 \leq f_j < k, \quad \gcd(f_j,k)=1.
\end{align*}
 By a change of variables  we get
\begin{align*}
      \mathcal{K} 
 &=    \sum_{\sigma \in \operatorname{SL}_2({\mathbb Z})} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10}} 1 
    =  \mathcal{K}_{1} + \mathcal{K}_{2} + \mathcal{K}_3, \\
      \mathcal{K}_1 &:=  \sum_{\substack{\sigma= \smqty(a & b \\ c& d) \in \operatorname{SL}_2({\mathbb Z}) \\mathfrak c=0}} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10}} 1   , \\
       \mathcal{K}_2  &:=    \sum_{\substack{\sigma= \smqty(a & b \\ c& d) \in \operatorname{SL}_2({\mathbb Z}) \\ c \neq 0}} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\  b_0= 0}} 1,  \\
     \mathcal{K}_3 &:=  \sum_{\substack{\sigma= \smqty(a & b \\ c& d) \in \operatorname{SL}_2({\mathbb Z}) \\ c \neq 0}} w_0(\sigma) \sum_{\substack{\sigma_j =\smqty(1 & f_j r_1 r_2 \\ & k) \\ \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\  b_0 \neq 0}} 1.
\end{align*} 
Here for $\sigma = \smqty(a &b \\ c& d)$
\begin{align*}
   \mqty(a_0 & b_0 \\mathfrak c_0 & d_0 )=  \sigma_2^{-1} \sigma \sigma_1  = \mqty(a-cf_2 r_1 r_2/k & f_1 r_1 r_2 a-f_2 r_1 r_2 d+kb-cf_1f_2 (r_1r_2)^2/k\\ c/k & d+cf_1 r_1 r_2/k).
\end{align*}

We have by Lemma \ref{le:charactersumbound} 
\begin{align*}
   \mathcal{K}_{1} \leq &   \sum_{\smqty(\pm 1 & b \\ & \pm 1) \in \operatorname{SL}_2({\mathbb Z})} w_0(\smqty(\pm 1 & b \\ & \pm 1) ) \sum_{\substack{ f_1,f_2 \leq k \\ |f_1 r_1 r_2 - f_2 r_1r_2 \pm k b| \leq 10 /L}} 1  \\
   \ll &  k  \sum_{\smqty(\pm 1 & b \\ & \pm 1) \in \operatorname{SL}_2({\mathbb Z})}  \sum_{\substack{ |f| \leq k \\ |f r_1 r_2 \pm k b| \leq 10 /L}} w_0(\smqty(\pm 1 & b \\ & \pm 1) ) \\
   \ll & k \sum_{|b_0| \leq 10 /L} w_0(\smqty(\pm 1 & b_0 \\ & \pm 1) ) \ll_\varepsilon Z^{\varepsilon} k \bigg(r_1 r_2 +  \frac{\gcd(r_1,r_2)}{L }\bigg)
\end{align*}
by combining $b_0 = f r_1 r_2  \pm k b$ since $\gcd(k,r_1r_2)=1$ and $b \mapsto w_0(\smqty(\pm 1 & b \\ & \pm 1) )$ is $r_1r_2$ periodic in $b$.

To bound $\mathcal{K}_2$ note that $b_0 = 0$ implies that $b \equiv 0 \pmod{r_1r_2}$ and $c \equiv 0 \pmod{k}$, so that
\begin{align*}
   \mathcal{K}_{2} = &   \sum_{\substack{\smqty(a &  b \\ c & d) \in \operatorname{SL}_2({\mathbb Z}) \\  0< |c| \leq 10 k L \\ b \equiv 0 \pmod{r_1r_2} \\ c \equiv 0 \pmod{k}}] } w_0(\smqty(a &  b \\ c & d) ) \sum_{\substack{ f_1,f_2 \leq k \\ |a - c f_2 r_1r_2/k | \leq 10 \\   | d + c f_1 r_1r_2/k |  \leq 10 \\ b_0 = 0 }} 1   
  \end{align*} 
 We have for $r_1r_2 | b, \gcd(ad,r_1r_2)=1,$ and $k|c$ that $w_0(\smqty(a &  b \\ c & d) )  = w_0(\smqty(1 &  0 \\ c & 1) ) =w_0(\smqty(1 &  0 \\ c/k & 1) )$, which depends only on $\gcd(c,r_1r_2)$. Thus, by Lemma \ref{le:charactersumbound} we get
  \begin{align*}
      \mathcal{K}_{2} \ll  &   \sum_{\substack{ 0< |c| \leq 10 k L \\ c \equiv 0 \pmod{k} } } w_0(\smqty(1 &  0 \\ c & 1) ) \sum_{\substack{a,b,d \\ ad-bc=1}}\sum_{\substack{ f_1,f_2 \leq k \\ |a - c f_2 r_1r_2/k | \leq 10 \\   | d + c f_1 r_1r_2/k |  \leq 10 \\ b_0 = 0 }} 1  \\
      \ll & \sum_{\substack{ 0< |c| \leq 10  L  } } w_0(\smqty(1 &  0 \\ c & 1) )\sum_{\substack{a,b,d \\ ad-bc k =1}}\sum_{\substack{ f_1,f_2 \leq k \\ |a - c f_2 r_1r_2 | \leq 10 \\   | d + c f_1 r_1r_2 |  \leq 10 \\ r_1r_2(f_2d-f_1 a) + c f_1f_2 (r_1r_2)^2 = kb }} 1
      \\
      \ll & \sum_{\substack{ 0< |c| \leq 10  L  } } w_0(\smqty(1 &  0 \\ c & 1) )\sum_{\substack{ f_1,f_2 \leq k }}\sum_{\substack{a,d \\ |a - c f_2 r_1r_2 | \leq 10 \\   | d + c f_1 r_1r_2 |  \leq 10 }} 1 \\
       \ll & k^2 \sum_{\substack{ 0< |c| \leq 10  L  } } w_0(\smqty(1 &  0 \\ c & 1) ) \ll_\varepsilon Z^{\varepsilon} k^2 L (r_1,r_2).
  \end{align*}

Finally, we have by the trivial bound $w_0(\sigma) \ll_\varepsilon (r_1r_2)^{1+\varepsilon}$ that
\begin{align*}
      \mathcal{K}_{3} \ll & (r_1r_2)^{1+\varepsilon}   \sum_{\substack{\smqty(a & b \\ c & d) \in \operatorname{SL}_2({\mathbb Z}) \\ c \neq 0  }}\sum_{\substack{\sigma_1,\sigma_2 \in T_{1,k} \\   \sigma_2^{-1} \sigma \sigma_1 = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\ b_0 \neq 0  }} 1.
     \\  \ll & \,  (r_1r_2)^{1+\varepsilon}   \sum_{\substack{\smqty(a_1 & b_1 \\ c_1 & d_1) \in \operatorname{M}_{2,k}({\mathbb Z}) \\ c \neq 0 \\ }}\sum_{\substack{\sigma_2 \in T_{1,k} \\   \sigma_2^{-1} \smqty(a_1 & b_1 \\ c_1 & d_1) = \smqty(a_0 & b_0 \\mathfrak c_0 & d_0 ) \\ |a_0| + |b_0| L + |c_0|/L + |d| \leq 10 \\ b_0 \neq 0}} 1. 
\end{align*}
Here
\begin{align*}
   \mqty(a_0 & b_0 \\mathfrak c_0 & d_0 )  =  \frac{1}{k} \mqty(k & -f_2 r_1r_2 \\ & 1) \mqty(a_1 & b_1 \\ c_1 & d_1)  = \frac{1}{k} \mqty(k a_1-f_2 r_1r_2  c_1 & k b_1-f_2 r_1r_2  d_1 \\ c_1 & d_1) = \frac{1}{k} \mqty(a_2 & b_2 \\ c_2 &  d_2).
\end{align*}
Thus, summing over $f_2$ and combining the variables (using $(k,r_1r_2)=1$) we get
\begin{align*}
  \mathcal{K}_{3} & \ll (r_1r_2)^{1+\varepsilon} \sum_{\substack{a_2 d_2 -b_2 c_2 = k^2 \\ |a_2|/k + |b_2|L/k + |c_2|/(kL) + |d_2| /k \leq 10  \\ b_2 c_2 \neq  0}} 1 \\
   & \ll  (r_1r_2)^{1+\varepsilon}  \sum_{\substack{a_2,d_2 \ll  k \\ a_2d_2 \neq k^2}} \tau(a_2 d_1 -k^2) \\
    & \ll  k^2(r_1r_2)^{1+\varepsilon} .
\end{align*}

By using the approximate functional equation for $L(s,\chi)$ \cite[Theorem 5.3]{IKbook}  (instead of the square $L(s,\chi)^2$ as in \cite{berke})
\begin{align*}
    L(s,\chi) = \sum_{n} \frac{\chi(n)}{n^s} V_s(\frac{n}{\sqrt{q}}) + \varepsilon(\chi,s) \sum_{n} \frac{\overline{\chi}(n)}{n^{1-s}} V_{1-s}(\frac{n}{\sqrt{q}}),
\end{align*}
we get (denoting $V_1(n,s) = V_s(\frac{n}{\sqrt{q}}) \chi(n) n^{-s},V_2(n,s) = \varepsilon(\chi,s)V_{1-s}(\frac{n}{\sqrt{q}})  \overline{\chi}(n)n^{1-s}$)
\begin{align*}
    |L(s,\chi)|^4 = \sum_{j_1,\dots,j_4 \in \{1,2\} } \sum_{n_1,\dots,n_4}  \prod_{k \leq 4}V_{j_k}(n_k).
\end{align*}

The contribution from $(j_1,j_2,j_3,j_4) $ which are not a permutation of $(1,1,2,2)$ may be handled trivially, for example, for $(j_1,j_2,j_3,j_4)=(1,2,2,2)$ we get  by  integration by parts
\begin{align} \begin{split}
        \int \bigg(\frac{n_2n_3n_4}{n_1}\bigg)^{it} V_s(\frac{n_1}{\sqrt{q}}) V_{1-s}(\frac{n_2}{\sqrt{q}})  &V_{1-s}(\frac{n_3}{\sqrt{q}})  V_{1-s}(\frac{n_4}{\sqrt{q}}) \varepsilon(\chi,s)^3 \omega(t/T) \mathrm d t  \\
    &\ll_J T \bigg(1+ \frac{|n_2n_3 n_4-n_1|  T^{1-O(\eta)}}{n_1}\bigg)^{-J}
\end{split}
\end{align}
Therefore, the part where $n_1 > T^{1-O(\eta)}$ contributes 
\begin{align*}
 \ll 1+  T \sum_{\substack{n_1,\dots,n_4 \ll T^\eta \sqrt{q T} \\ n_1 > T^{1-O(\eta)}  \\ n_2n_3 n_4 = n_1 (1+ O(T^{-1 + O(\eta)})) } } \frac{1}{\sqrt{n_1 n_2 n_3 n_4}} \ll& 1+  T (qT)^{O(\eta)} \sum_{\substack{T^{1-O(\eta)}< n_1 \ll T^\eta \sqrt{q T}  } } \bigg(\frac{1 }{n_1^2}  + \frac{1 }{T n_1}\bigg) \\
 \ll &(qT)^{O(\eta)}.
\end{align*}

In the remaining part we can assume by symmetry that $(j_1,j_2,j_3,j_4)= (1,2,2,1)$ and we may truncate the variables $(a,b,c,d)=(n_1,n_2,n_3,n_4)$ to ranges $A,B,C,D \ll T^\eta \sqrt{q T}$. Denote $X=AD \ll q T$ so that $H \leq T^\eta X/T$. Then we may assume that $X > T^{1-O(\eta)}$ (otherwise $h=0$) and further that $A,C > \sqrt{X}$ (otherwise we can swap $b \leftrightarrow c$, $a\leftrightarrow d$). This implies that $Z^{-\eta} (X/qT)^{1/2} < C/A < Z^{\eta} (qT/X)^{1/2}$, which is stronger than \eqref{eq:ratioassumption}. The bound for the error term in the application of Theorem \ref{thm:twisteddetwbound} is consequently improved to
\begin{align*}
 \ll   T^{O(\eta)}   T^{1/2+\theta}\,  q.
\end{align*}
